// 原创术语释义与学习例子；来源指向规范及项目维护者资料，不复制题库原题。
const src=(label,url)=>({label,url});
const man=(name,section=7)=>src(`Linux man-pages：${name}(${section})`,`https://man7.org/linux/man-pages/man${section}/${name}.${section}.html`);
const rfc=n=>src(`IETF RFC ${n}`,`https://www.rfc-editor.org/rfc/rfc${n}`);
const pg=page=>src('PostgreSQL 18 官方文档',`https://www.postgresql.org/docs/18/${page}.html`);
const owasp=page=>src('OWASP Cheat Sheet Series',`https://cheatsheetseries.owasp.org/cheatsheets/${page}_Cheat_Sheet.html`);
const s=(key,term,english,aliases,definition,example,distinction,pitfall,followup,followupAnswer,sources,difficulty=2,depth=2,frequency=2)=>({key,term,english,aliases,definition,example,distinction,pitfall,followup,followupAnswer,sources,difficulty,depth,frequency});

export const groups=[
{id:'os',name:'操作系统术语',description:'执行单元、地址空间、文件与内核接口的双语概念。',rows:[
s('process','进程','Process',[], '操作系统为正在执行的程序组织资源和执行状态的实体，通常拥有独立虚拟地址空间、进程标识及一组打开的文件。相同可执行文件可以运行成多个互相隔离的进程。','同时打开两个独立服务实例，它们使用相同程序文件，却各自持有连接和内存。','程序是静态代码及数据；进程是其运行实例。线程是进程内的执行单元。','以为进程之间绝不共享资源；共享映射、继承描述符等可以显式共享。','两个进程的同一个虚拟地址一定对应同一物理页吗？','不一定。地址转换依赖各自地址空间，只有共享映射等条件下才可能指向同一物理页。',[man('fork',2),man('proc',5)],1,2,3),
s('thread','线程','Thread',['POSIX thread','Pthread'], '操作系统调度执行的一条指令流，在同一进程中通常与其他线程共享地址空间、打开文件和进程级属性，同时保留自己的寄存器状态、栈和线程标识。','Web服务的两个工作线程能访问同一堆对象，但各自调用链位于不同栈。','共享地址空间减少通信成本，也要求对共享可变状态进行同步；线程不等于协程。','把线程栈误认为其他线程绝对不可访问的安全边界。','一个线程关闭共享文件描述符会影响其他线程吗？','可能影响整个进程中使用该描述符的线程；需协调生命周期，避免关闭后描述符复用造成误操作。',[man('pthreads')],1,2,3),
s('syscall','系统调用','System Call',['syscall'], '用户程序请求内核执行受保护操作的接口，例如创建进程、读取文件和建立套接字。它通过规定的调用约定跨越权限边界，返回结果或错误，并可能阻塞当前线程。','读取文件时，库函数最终可能调用read系统调用请求内核复制数据。','库函数不一定调用内核；例如纯内存字符串处理通常在用户态完成。','认为每次调用标准库函数都发生一次系统调用。','一次printf一定对应一次write吗？','不一定。标准I/O可能缓冲多个输出后统一写入，也可能因格式化或刷新策略拆分写入。',[man('syscalls',2),man('stdio',3)],1,2,3),
s('kernel-space','内核空间','Kernel Space',[], '操作系统内核运行并管理关键结构的受保护环境，具备受控访问硬件和系统资源的能力。用户进程必须通过规定接口请求服务，普通指针不能任意读写内核内部数据。','应用提交磁盘读请求后，驱动在内核控制下协调设备并完成请求。','内核态是执行权限状态；内核空间是地址及资源组织概念，两者相关但不宜混为同一词。','以为root用户程序天然一直在内核态运行。','root程序为什么仍会遇到非法内存访问？','用户身份不取消虚拟地址和内存保护机制，未映射地址或权限不符仍可触发异常。',[man('intro',2),man('capabilities')],2,2,2),
s('context-switch','上下文切换','Context Switch',[], '处理器从一个执行上下文转到另一个时保存并恢复必要状态的过程，可涉及寄存器、调度状态和地址空间信息。切换本身及缓存局部性变化都会消耗资源。','一个工作线程等待磁盘后，调度器把CPU交给另一条可运行线程。','用户态进入内核态不必然更换正在运行的线程；权限切换不等于调度切换。','只按寄存器保存指令数估算切换代价，忽略缓存和TLB影响。','增加线程数为何可能降低吞吐？','过多可运行线程争用CPU，切换和缓存失效增加，锁竞争也可能扩大，须结合阻塞比例测量。',[man('sched'),man('getrusage',2)],2,3,3),
s('virtual-memory','虚拟内存','Virtual Memory',['VM'], '通过地址转换和保护机制为进程提供逻辑地址空间的内存管理抽象，使程序看到的连续地址不必对应连续物理内存，并支持隔离、共享映射和按需装入等能力。','进程映射一个大文件，只访问少量页面时不必预先把整个文件装入物理内存。','虚拟内存不等于交换分区；即使关闭swap，地址转换与隔离仍然存在。','把虚拟地址空间大小直接当成实际物理内存占用。','预留一大片虚拟地址是否立即消耗同样大小的RAM？','通常不会按地址区间大小立即分配全部物理页；是否承诺、实际触页和映射类型都会影响占用。',[man('mmap',2),man('proc',5)],2,2,3),
s('memory-page','内存页','Memory Page',['Page'], '虚拟内存系统以固定粒度组织映射和保护时使用的地址区间单位，虚拟页映射到物理页帧或其他后备状态。页大小依体系结构和配置而定，也可能同时支持大页。','系统按页建立文件映射；修改其中一个字节可能使整页成为脏页。','内存页不同于磁盘扇区、文件系统块和数据库页，数值偶然相同也不能视为同一层。','把常见的4 KiB当成所有平台和映射的唯一页大小。','使用大页有什么代价？','可能减少地址转换开销，但分配与回收粒度更粗，内存浪费、整理和停顿风险需实测。',[man('getpagesize',2),man('mmap',2)],1,2,2),
s('page-fault','缺页异常','Page Fault',[], '处理器访问某个虚拟页时发现映射或访问条件不能直接满足而产生的异常，交由操作系统判断是装入、按需分配、写时复制还是非法访问，并非都表示发生磁盘读取。','首次写入匿名映射可触发分配物理页；读取未驻留文件页可能需要存储I/O。','轻微缺页通常无需读取后备存储，重大缺页涉及相应I/O；非法权限访问也可能最终终止程序。','把缺页次数等同磁盘读次数，或把所有缺页都当成错误。','常驻内存仍很充足时为何有缺页？','按需建立映射、首次访问、写时复制等不要求内存不足，仍可能触发缺页处理。',[man('getrusage',2),man('mmap',2)],2,3,2),
s('tlb','地址转换后备缓冲','Translation Lookaside Buffer',['TLB'], '处理器缓存近期虚拟地址到物理地址转换结果的结构，用来减少重复查页表的开销。其条目还涉及访问权限与地址空间身份，命中和失效影响访存性能。','访问大量随机分散页面时，地址转换缓存可能频繁未命中。','CPU数据缓存存放数据或指令内容；TLB缓存地址转换，二者未命中原因和代价不同。','看到TLB未命中就认定会发生缺页或磁盘读取。','TLB未命中而页已驻留时会怎样？','处理器或内核按体系结构机制查页表并填充转换，通常不需要从磁盘装入页面。',[src('Linux 内核：缓存与TLB刷新','https://docs.kernel.org/core-api/cachetlb.html')],2,3,2),
s('copy-on-write','写时复制','Copy-on-Write',['COW'], '多个使用者先共享同一份底层数据，在某个使用者需要修改时才分离并复制相应部分的机制。它把复制成本推迟到实际写入，并要求正确处理共享状态与写入权限。','fork后的父子进程可暂时共享内存页，一方写入相关页才产生私有副本。','写时复制不是任意写操作都复制全部对象；实际粒度取决于实现，如页面或数据块。','认为fork共享页意味着父子进程能直接看见彼此后续普通变量写入。','fork后大量写内存为什么成本上升？','写入会触发页级分离、分配和复制，越多被修改页面越接近实际复制相应内存的成本。',[man('fork',2)],2,3,2),
s('file-descriptor','文件描述符','File Descriptor',['FD'], '进程用于引用已打开I/O对象的非负整数，通过进程的描述符表关联到内核维护的打开状态。它可以代表普通文件、套接字、管道等对象，而不只是磁盘文件。','服务接受客户端连接后获得一个描述符，用它执行读写并最终关闭。','描述符整数是进程内索引；打开文件描述关联偏移和状态，多次dup可指向同一个打开描述。','把描述符当成全局唯一永久句柄，关闭后仍继续使用原数字。','dup后的两个描述符文件偏移独立吗？','通常共享同一个打开文件描述及其偏移；重新open才通常建立另一份打开状态。',[man('open',2),man('dup',2)],1,3,3),
s('inode','索引节点','Index Node',['inode'], '类Unix文件系统用于记录文件元信息和数据定位信息的结构，文件类型、权限、所有者和链接数等通常与其关联。目录项把名称映射到inode，名称并不直接储存在inode中。','同一文件的两个硬链接名称可映射到相同设备上的同一inode。','路径名用于查找；inode标识文件系统内对象，跨设备比较必须同时考虑设备身份。','认为删除某个路径名就一定立即清除文件数据。','文件删除后空间为何可能尚未释放？','仍有硬链接或进程打开引用时，文件对象可能继续存在，最后引用释放后才回收相应存储。',[man('inode'),man('unlink',2)],2,2,2),
s('hard-link','硬链接','Hard Link',[], '文件系统中另一个指向同一文件对象的目录项，与原名称共享inode和文件内容。普通文件的每个硬链接地位相同，删除一个名称并不会自动使其他名称失效。','给报告文件创建第二个硬链接后，通过任一名称修改都会看到同一份内容。','符号链接存储另一个路径；硬链接直接共享文件对象，通常不能跨文件系统创建。','把硬链接理解为独立备份副本。','修改原名指向的文件会影响硬链接吗？','若是在同一个inode中写入会影响；若应用用新文件原子替换原路径，另一个硬链接仍指向旧inode。',[man('link',2)],2,3,2),
s('symbolic-link','符号链接','Symbolic Link',['Symlink','软链接'], '保存一个目标路径字符串的特殊文件，访问时由路径解析机制继续查找目标。目标可以不存在，可以位于另一个文件系统，也可因相对路径的解释位置而得到不同结果。','把current链接指向某个版本目录以切换部署入口。','符号链接拥有自身文件对象，不与目标共享inode；链接存在不代表目标存在。','检查链接后再使用目标而不考虑目标可能被替换。','相对目标路径通常以哪里为基准？','以符号链接所在目录为基准解析，而不是以执行命令时的当前目录为基准。',[man('symlink')],1,2,2),
s('page-cache','页缓存','Page Cache',[], '操作系统用于缓存文件内容等后备数据的内存机制，使后续读取可避免重复访问较慢存储，并缓冲部分写入。脏页回写、回收与持久化保证是不同的处理环节。','第二次读取相同文件常比首次快，因为数据可能已在内核页缓存中。','应用内存缓存由应用管理；页缓存由内核管理，复制到缓存不等于已持久化到设备。','把write成功返回当成掉电后必然可恢复的证明。','如何表达关键文件更新的持久化要求？','按平台语义使用fsync等同步操作，并考虑新建或重命名涉及目录的持久化及设备保证。',[man('fsync',2),src('Linux 内核：页缓存','https://docs.kernel.org/mm/page_cache.html')],2,3,3),
s('memory-map','内存映射','Memory Mapping',['mmap'], '把文件、设备或匿名存储区域关联到进程虚拟地址区间的机制，程序可用内存访问方式操作相应内容。共享、私有映射的修改可见性和回写语义不同。','只读映射大型索引文件后，程序按偏移直接访问其中的记录。','mmap改变访问接口和映射关系，不意味着完全没有缺页、复制或存储延迟。','认为关闭原文件描述符就会自动撤销已经建立的映射。','MAP_PRIVATE修改会写回原文件吗？','通常不会把私有映射的写时复制修改写回文件；共享写回应使用相应映射和同步语义。',[man('mmap',2)],2,3,3),
s('blocking-io','阻塞I/O','Blocking Input/Output',['Blocking I/O'], '执行I/O操作时，如果当前条件不能满足所请求进展，调用线程可进入等待，直到条件满足、出错或被中断。等待的是调用线程，不表示整个系统停止工作。','阻塞套接字读取在无数据时等待，同时其他线程仍可处理请求。','同步描述操作完成方式，阻塞描述等待行为；两组概念不能简单一一对应。','把阻塞等待说成持续占满CPU忙等。','阻塞read是否总会返回请求的全部字节？','不会。读取可返回较少字节，流协议应用需要循环处理并正确识别EOF、错误和消息边界。',[man('read',2),man('socket',7)],1,2,3),
s('nonblocking-io','非阻塞I/O','Nonblocking Input/Output',['Nonblocking I/O'], 'I/O对象被设为非阻塞后，无法立即取得进展的操作通常立即返回相应状态，由程序决定稍后重试或等待事件。它改变等待策略，并不让操作自动完成或天然并行。','非阻塞套接字没有可读数据时返回EAGAIN，事件循环等待可读通知后再尝试。','非阻塞不是异步完成通知；应用通常仍需自己调用读写并处理部分成功。','对EAGAIN无休止立即重试，造成忙循环。','可写事件到来后能一次写完任意大消息吗？','不能。可写通常只表示存在一定可用容量，应保存未写偏移并继续处理部分写入和后续就绪事件。',[man('fcntl',2),man('socket',7)],2,3,3),
s('io-multiplexing','I/O多路复用','Input/Output Multiplexing',['I/O Multiplexing'], '利用一个等待机制监测多个I/O对象状态，发现就绪后再分派实际读写工作，从而用较少线程管理大量连接。它监测可操作条件，本身不执行所有业务处理。','服务器用epoll等待数千连接中的可读事件，再按连接状态解析请求。','并发连接多不等于CPU任务并行多；耗时计算仍可能阻塞单一事件循环。','认为就绪通知保证之后read绝不会返回EAGAIN。','边缘触发为什么常配合读到EAGAIN？','只在状态变化时通知时，若遗留可读数据却不继续排空，可能没有新的变化再次提醒；同时要保证调度公平。',[man('epoll'),man('poll',2)],2,3,3),
s('interrupt','中断','Interrupt',[], '处理器响应外设或系统事件而转入相应处理流程的机制，使事件不必完全依赖程序持续轮询。处理器状态保存、屏蔽和后续延迟处理均受体系结构与内核规则约束。','网卡收到数据后可通知内核，再由内核安排后续网络处理。','中断是事件处理机制；信号是操作系统提供给进程的通知抽象，不能把二者直接等同。','认为每个网络包必然触发一次独立硬中断。','为何需要中断合并或批处理？','高事件速率时减少通知和切换开销，但批处理过度可能增加延迟，需要在吞吐和响应间权衡。',[man('proc_interrupts',5),src('Linux 内核：通用IRQ','https://docs.kernel.org/core-api/genericirq.html')],2,3,2),
s('signal','信号','Signal',[], '类Unix系统向进程或线程传达异步事件的通知机制，每种信号有规定编号和默认动作，部分可安装处理函数或阻塞。标准信号合并行为与实时信号排队规则不同。','服务收到SIGTERM后停止接收新工作并在超时范围内完成清理。','信号不是可以任意传输结构化消息的普通消息队列；处理函数执行环境受严格限制。','在信号处理函数里调用并非异步信号安全的复杂库操作。','为何不能依赖捕获SIGKILL做清理？','SIGKILL不能被捕获、阻塞或忽略；应设计持久状态恢复和外部资源回收，不能只依赖退出钩子。',[man('signal'),man('signal-safety')],2,3,2),
s('ipc','进程间通信','Interprocess Communication',['IPC'], '不同进程在各自隔离的执行和地址环境间交换数据、通知事件或协调操作的机制总称，包括管道、套接字、共享内存和消息队列等，选型取决于数据与同步需求。','父子进程通过管道传递处理结果，另一组进程用Unix套接字交换请求。','共享内存可避免部分数据复制，但仍需另外安排同步、生命周期和访问控制。','把“用了共享内存”当成并发安全已经解决。','为什么跨机器通信一般不能直接使用本机共享内存？','普通共享内存依赖同一内核和物理资源；跨主机需要网络协议及分布式故障处理，语义和代价不同。',[man('pipe',7),man('unix'),man('shm_overview')],1,2,3),
s('deadlock','死锁','Deadlock',[], '一组执行实体因互相等待对方持有的资源而无法继续推进的状态，典型表现是形成无法自行解除的等待环。避免、预防、检测和恢复是不同的应对策略。','线程甲持有锁A等待B，线程乙持有锁B等待A，双方都不释放已持有的锁。','长时间等待未必是死锁；饥饿与活锁也可能无法完成，但等待关系不同。','以为给锁加超时就自动恢复了所有业务状态。','统一加锁顺序为什么有帮助？','所有参与者按同一严格顺序获取锁可破坏循环等待；仍需审查回调、隐式锁和动态资源排序。',[man('pthread_mutex_lock',3),pg('explicit-locking')],2,3,3),
s('semaphore','信号量','Semaphore',[], '维护非负计数并提供原子获取和释放操作的同步原语，可表示可用资源数量或控制并发进入数。等待行为与公平性依具体实现，计数本身不记录业务资源的所有权。','用初值为8的信号量限制同时执行的图像转换任务数量。','互斥锁强调临界区互斥和所有者规则；计数信号量可允许多名持有者且通常无同样的所有权约束。','任务异常退出未归还许可，长期耗尽可用计数。','如何避免许可泄漏？','只在成功获取后安排finally或作用域清理释放，并避免重复释放；取消与超时路径也要逐项验证。',[man('sem_overview')],2,3,2),
s('cgroups','控制组','Control Groups',['cgroups','cgroup'], 'Linux内核把进程组织为层级分组并进行资源统计、限制和分配的机制，常用于CPU、内存及I/O管理。它负责资源控制，不能单独构成完整的容器隔离边界。','把服务放进限定内存与CPU配额的控制组，避免它无限侵占宿主机资源。','命名空间隔离“能看到什么”；cgroup控制“能使用多少”，二者职责不同。','把容器设置了内存限制理解为已预留且独占同样内存。','达到内存上限可能怎样？','可能发生回收、分配失败或组内OOM处置，具体取决于控制器与配置；需要监测事件并为故障恢复留余量。',[man('cgroups'),src('Linux 内核：cgroup v2','https://docs.kernel.org/admin-guide/cgroup-v2.html')],2,3,2),
]},
{id:'engineering',name:'软件工程与研发流程术语',description:'需求、架构、测试及持续交付的工程词汇。',rows:[
s('acceptance-criteria','验收标准','Acceptance Criteria',['AC'], '用可观察结果和明确边界描述某项需求达到完成条件的判据，帮助开发、测试与使用者对成功形成共同理解。标准应覆盖关键正常与异常行为，不能只写“效果好”或“已开发”。','题目导入要求合法文件成功、错误记录给定位、失败不留下半成品，并有数量统计。','需求描述要解决的问题；验收标准把完成状态变成可验证行为，两者关联但不是同一句空泛目标。','只按按钮是否存在验收，忽略数据权限、错误处理和恢复行为。','性能验收怎么避免含糊？','明确数据规模、并发条件、统计口径和阈值，例如固定环境下某分位响应时延，而不只写“速度快”。',[src('Atlassian：验收标准','https://www.atlassian.com/work-management/project-management/acceptance-criteria')],1,2,2),
s('definition-of-done','完成的定义','Definition of Done',['DoD'], '团队对增量达到可用质量状态的共同标准，描述代码、验证、文档等应满足的质量要求。它为多项工作提供一致基线，与某一需求特有的业务验收条件相互补充。','团队约定关键检查通过、变更可回滚且必要使用说明已更新，才能把增量称为完成。','验收标准聚焦一项需求的业务行为；DoD是增量质量的共同承诺。','把开发者说“代码写完”当作已经满足团队的完成标准。','DoD应该永远固定不变吗？','可以随能力和质量目标改进，但应共同理解并持续遵守；不能为了赶进度悄悄降低标准。',[src('Scrum Guide 2020：完成的定义','https://scrumguides.org/scrum-guide.html')],1,2,2),
s('technical-debt','技术债','Technical Debt',[], '用财务债务类比说明当前设计或实现选择带来的未来变更成本，既可能来自有意识取舍，也可能来自认知不足。有效管理需要识别成本、风险和偿还时机，而不是把所有不喜欢的代码统称为债务。','快速交付时暂时复制相似逻辑，后续规则变化需要多处同步修改。','普通新需求不自动等于技术债；债务强调既有结构使未来工作产生额外成本。','只记录“以后重构”，却没有说明债务影响、触发条件或处理优先级。','如何判断是否立即偿还？','结合未来变更频率、故障风险与偿还成本，优先处理持续产生高额成本或阻碍关键需求的部分。',[src('Martin Fowler：Technical Debt','https://martinfowler.com/bliki/TechnicalDebt.html')],1,3,2),
s('bounded-context','限界上下文','Bounded Context',['BC'], '领域驱动设计中为一套术语与模型规定适用边界的概念，同一词在不同边界内可有不同精确含义。上下文之间需要显式映射与协作，不宜强行共享一套包罗万象的数据模型。','销售中的“客户”强调购买与联系人，风控中的“客户”强调风险主体和审查状态。','限界上下文是模型语义边界，不必与进程、仓库或微服务一一对应。','按数据库表数量机械拆上下文，却没有分析业务语言和职责。','两个上下文需要交换数据怎么办？','定义边界接口、事件或转换层，明确字段含义与所有权，避免直接依赖对方内部模型。',[src('Martin Fowler：Bounded Context','https://martinfowler.com/bliki/BoundedContext.html')],2,3,2),
s('cohesion','内聚','Cohesion',[], '描述一个模块内部职责与组成部分围绕共同目的关联紧密程度的设计概念。高内聚通常使变更理由更集中、理解成本更低，但判断应依据业务职责，而非仅看文件长度或方法数量。','把库存预留、释放与状态约束放在明确的库存模块中共同维护。','耦合描述模块之间依赖；内聚描述模块内部关联，两者需一起权衡。','把所有“工具函数”塞进一个公共类，以为放在一起就是高内聚。','如何从变更历史观察内聚问题？','若同一业务规则变化总要跨多个无关模块同步，或一个模块被许多互不相干需求反复修改，可能说明职责划分需要检查。',[src('Microsoft：架构设计原则','https://learn.microsoft.com/en-us/dotnet/architecture/modern-web-apps-azure/architectural-principles')],2,3,3),
s('coupling','耦合','Coupling',[], '描述模块之间依赖程度与依赖形式的设计概念，包括接口、数据结构、时序及部署等维度。降低不必要耦合有助于独立变更，但完全没有依赖既不现实，也不是架构的唯一目标。','上游只依赖稳定公开接口，比直接读写对方内部表结构更容易独立演进。','模块数量多不代表低耦合，跨模块共享数据库或同步发布也可能造成强依赖。','把所有调用改成消息队列，就宣称业务和时间耦合已经消失。','异步通信仍有什么耦合？','事件结构、语义、顺序、保留和恢复流程仍形成契约，需要版本管理和消费端兼容策略。',[src('Martin Fowler：微服务特征','https://martinfowler.com/articles/microservices.html')],2,3,3),
s('adr','架构决策记录','Architecture Decision Record',['ADR'], '以简短文档保存重要设计决定、所处背景、备选方案和后果的方式，让后续维护者理解为什么如此选择。它记录当时约束与取舍，不要求把所有代码细节转写成冗长文档。','记录为何便携版选SQLite、单机限制是什么，以及何时需要重新评估。','设计说明描述当前结构；ADR保留促成结构的决策背景和后果，可相互链接。','只写“决定使用某技术”，不说明问题和放弃其他方案的依据。','决定被新方案取代时怎么办？','保留原记录并标注被取代，链接新决策，使读者能追踪约束变化而非悄悄重写历史。',[src('Michael Nygard：Documenting Architecture Decisions','https://cognitect.com/blog/2011/11/15/documenting-architecture-decisions')],1,2,2),
s('contract-test','契约测试','Contract Test',['Consumer-Driven Contract Test'], '验证服务提供者与消费者对接口格式、字段和交互约定理解一致的测试方式，可把消费者实际依赖转成提供者可验证的契约。它覆盖接口协作边界，不等于完整端到端业务验证。','消费者声明需要订单响应中的id和状态字段，提供者在发布前验证仍满足这些约定。','单元测试检查局部行为；契约测试检查协作约定，集成测试还可能覆盖真实连接与环境。','契约测试通过后就取消权限、事务和完整业务流程测试。','增加响应字段是否一定破坏契约？','通常可做兼容扩展，但严格解析器、签名规则或精确匹配断言可能受影响，仍应按真实消费者行为验证。',[src('Martin Fowler：Contract Test','https://martinfowler.com/bliki/ContractTest.html'),src('Pact：契约测试介绍','https://docs.pact.io/getting_started/how_pact_works')],2,3,2),
s('regression-test','回归测试','Regression Testing',[], '在变更后检查原有能力未发生非预期退化的验证活动，可以复用自动化或人工测试并按风险选择范围。回归关注相对于既有行为的变化，不是只把新功能从头演示一遍。','调整题目标签存储后，验证检索、分享导入和原有练习卷仍能正常使用。','复测通常确认特定缺陷已修复；回归还关注修复或变更是否破坏其他行为。','仅跑与实现一一对应的断言，却没有覆盖重要跨模块行为。','如何选择回归范围？','结合依赖关系、变更规模、历史故障和业务影响，优先覆盖关键路径及边界，再按新证据扩大验证。',[src('ISTQB：术语表','https://glossary.istqb.org/')],1,2,3),
s('test-double','测试替身','Test Double',['Stub','Mock','Fake'], '测试中替代真实协作对象的总称，可提供固定响应、记录交互或实现简化功能。不同替身承担的目的不同，选择应让测试验证可观察行为并控制必要依赖，而不是复制整个实现。','测试邮件流程时用记录发送内容的替身，避免真的向外部收件人发信。','Stub侧重提供答案，Mock常验证交互，Fake提供简化可工作实现；各库命名可能略有差异。','过度断言内部方法调用顺序，使安全重构也大量失败。','什么时候不适合只用替身？','数据库隔离、协议解析与第三方真实兼容等风险需适当集成验证，替身无法证明真实边界一定一致。',[src('Martin Fowler：Test Double','https://martinfowler.com/bliki/TestDouble.html')],2,3,3),
s('ci','持续集成','Continuous Integration',['CI'], '团队频繁把小批变更合并到共享主线，并通过自动构建与检查尽早发现集成问题的开发实践。流水线是实现手段之一，长期隔离分支即使每天跑测试也不自动等于持续集成。','开发者频繁提交可验证的小变更，主线合并后立即构建并验证关键行为。','持续集成关注集成频率和反馈；持续交付进一步关注随时可安全发布。','只安装CI服务器，却长期不合并或对失败构建置之不理。','主线检查失败后应如何处理？','优先恢复可用主线，定位并修复或回滚相关变更，保持反馈可信并减少其他工作继续叠加风险。',[src('Martin Fowler：Continuous Integration','https://martinfowler.com/articles/continuousIntegration.html')],1,2,3),
s('continuous-delivery','持续交付','Continuous Delivery',['CD'], '通过自动化与质量控制使软件保持可随时可靠发布的状态的工程能力，发布到生产仍可由人工决定。它包含构建、验证、环境与部署准备，不能仅以打出压缩包为完成标准。','每次通过流水线的版本都具备可追溯产物、部署说明和必要回滚条件，按业务需要发布。','持续部署通常进一步自动把合格变更发布到生产；两者都常缩写CD，阅读时应说明具体含义。','把人工最终批准视为不可能做到持续交付。','为什么应构建一次并推广同一产物？','减少不同环境重新编译造成的漂移，使验证过的版本与最终部署内容有明确对应关系。',[src('Jez Humble：Continuous Delivery原则','https://continuousdelivery.com/')],1,3,3),
s('semantic-versioning','语义化版本','Semantic Versioning',['SemVer'], '按公开API兼容性规则使用主版本、次版本和修订版本表达变更的版本约定，含预发布和构建元信息规则。它只有在项目明确API边界并遵循规则时才有意义，版本号本身不能强制兼容。','公开接口不兼容改动提升主版本，兼容新增能力提升次版本，兼容修复提升修订版本。','构建元信息与预发布标识的排序语义不同，不能简单按普通字符串排序所有版本。','认为任何补丁版本升级在任意项目中都绝对零风险。','0.y.z阶段与稳定版本有什么不同？','规范把初始开发阶段的公开API视为可能随时变化，消费者需核对项目承诺和实际变更。',[src('Semantic Versioning 2.0.0规范','https://semver.org/spec/v2.0.0.html')],1,2,2),
s('feature-flag','功能开关','Feature Flag',['Feature Toggle'], '在运行时或部署配置中控制某项行为是否对特定用户、环境或比例流量启用的机制，可把代码部署与功能开放分离。开关需要生命周期、默认值和回收安排，否则分支组合会增加维护成本。','先部署新推荐逻辑，再只给小比例用户启用并观察结果。','开关不等同回滚二进制；旧新路径都可能已经写入数据，切回行为还需考虑状态兼容。','把长期权限控制和临时发布开关混用，且忘记清理失效分支。','关闭开关能完全撤销已发生数据变更吗？','通常不能，应为写入格式、迁移和副作用设计独立恢复方案，不能只依赖布尔开关。',[src('Martin Fowler：Feature Toggles','https://martinfowler.com/articles/feature-toggles.html')],2,3,2),
s('observability','可观测性','Observability',[], '依据系统产生的输出推断内部状态和行为的能力，在软件中常通过日志、指标、追踪及上下文关联实现。目标是能回答故障和性能问题，采集数据多并不自动意味着具备有效诊断能力。','用请求追踪把API延迟关联到数据库调用，再用指标判断影响范围。','监控检查预设现象；可观测性还支持对未预先穷举的问题形成可验证解释，两者相互依赖。','无限记录全部原始输入却忽视隐私、基数、成本和数据关联。','如何判断新增观测点是否有价值？','先明确要回答的问题或决策，验证字段、采样和保留是否足够，并确保不泄露敏感凭据或用户数据。',[src('OpenTelemetry：可观测性入门','https://opentelemetry.io/docs/concepts/observability-primer/')],1,3,3),
]},
{id:'operations',name:'运维与可靠性术语',description:'服务目标、恢复指标与可控发布。',rows:[
s('sli','服务级别指标','Service Level Indicator',['SLI'], '衡量用户实际获得服务质量的量化指标，应具有明确分子、分母、观察窗口和测量位置。指标可描述成功率、延迟或数据新鲜度，内部CPU占用通常不能直接替代用户体验指标。','把规定窗口内成功完成的有效检索请求占全部有效检索请求的比例定义为可用性SLI。','SLO是目标，SLI是测量，SLA是可能包含后果的约定，不应互换。','只从服务器无异常日志推断用户请求全部成功。','为什么需要定义哪些请求算有效？','客户端取消、恶意流量与依赖故障等口径会影响分母，必须事先规定并避免用分类规则掩盖真实体验。',[src('Google SRE：服务级别目标','https://sre.google/sre-book/service-level-objectives/')],2,3,3),
s('slo','服务级别目标','Service Level Objective',['SLO'], '在指定时间窗口内对某个服务级别指标设定的目标，用于约束可靠性与变更决策。合理目标应贴合用户需求和实现成本，并能通过明确测量检验，而不是没有统计口径的承诺。','约定30天窗口中99.9%的有效读取请求成功，并监测错误预算消耗。','SLA常涉及对外协议及未达标后果；SLO可用作内部工程目标，不一定有赔偿条款。','把99.9%成功率未经转换就当成完全等价的固定停机时长。','为什么不能只追求100%目标？','现实故障与成本约束使绝对目标难以保证，合理预算能指导发布、修复和资源投入，而不掩饰影响。',[src('Google SRE：服务级别目标','https://sre.google/sre-book/service-level-objectives/')],2,3,3),
s('error-budget','错误预算','Error Budget',[], '在给定SLO与观察窗口下允许的不良事件或失败比例额度，用来量化可靠性余量并指导变更风险。预算可按请求或时间等口径计算，消耗策略应由团队预先约定而非事后随意调整。','请求成功率目标99.9%对应0.1%的失败预算，消耗过快时优先修复稳定性。','错误预算不等于鼓励制造故障；它把用户可接受风险转成可讨论的工程约束。','预算耗尽后只停止发布，却不调查正在持续消耗预算的原因。','为什么还要观察预算燃烧率？','仅看窗口总余量可能反应迟缓，快速消耗表明短期高风险，可触发更及时的告警和处置。',[src('Google SRE Workbook：错误预算策略','https://sre.google/workbook/error-budget-policy/')],2,3,2),
s('rto','恢复时间目标','Recovery Time Objective',['RTO'], '业务或服务在中断后希望于多长时间内恢复到约定可用状态的目标，起止口径需明确。它约束恢复流程、人员和基础设施准备，不是仅统计把备份文件复制完成所需时间。','关键服务计划在事故确认后30分钟内恢复核心读写，并定期演练实际流程。','RPO衡量可接受数据回退范围；RTO衡量恢复时长，二者解决不同问题。','有备份就直接宣称RTO很短，忽略定位、环境重建和一致性校验。','如何验证RTO是否可实现？','定期做接近真实规模的恢复演练，记录所有步骤耗时及依赖，检查恢复后业务可用而不只进程启动。',[src('AWS：灾难恢复选项','https://docs.aws.amazon.com/whitepapers/latest/disaster-recovery-workloads-on-aws/disaster-recovery-options-in-the-cloud.html')],2,3,3),
s('rpo','恢复点目标','Recovery Point Objective',['RPO'], '发生中断后可接受丢失的数据范围，通常用距事故发生前最近可恢复点的时间表达。它由备份、复制及日志持久化策略共同决定，必须区分理想目标与故障条件下实际可恢复的位置。','每天一次备份若无连续日志，最坏可能回退接近一天的数据，而非零数据损失。','RTO关心恢复多久；RPO关心恢复到多近的数据点，快速恢复旧备份仍可能不满足RPO。','把异步副本数量多当成RPO必为零的证明。','如何降低RPO？','可增加备份频率、持续保留恢复日志或采用适当同步确认机制，并验证日志完整与恢复链实际可用。',[src('AWS：灾难恢复规划','https://docs.aws.amazon.com/whitepapers/latest/disaster-recovery-workloads-on-aws/disaster-recovery-planning.html')],2,3,3),
s('infrastructure-as-code','基础设施即代码','Infrastructure as Code',['IaC'], '用可版本化的声明或程序描述并管理基础设施配置的实践，使变更可评审、重复执行和追踪。它需要处理状态、密钥、环境差异与漂移，并不意味着所有命令脚本天然满足可复现和安全要求。','通过受控配置创建服务、网络和存储资源，先评审计划再应用变更。','配置文件存在不等于IaC流程完整；需要明确哪些资源受管理以及如何检测实际状态偏差。','把生产密钥直接写入版本库，或跳过变更计划就批量应用。','手工改过线上资源后该怎么办？','核对漂移原因，把需要保留的变更纳入声明与评审，或按计划恢复，避免下次自动执行意外覆盖。',[src('HashiCorp：基础设施即代码','https://developer.hashicorp.com/terraform/tutorials/aws-get-started/infrastructure-as-code')],2,3,2),
s('immutable-infrastructure','不可变基础设施','Immutable Infrastructure',[], '通过构建新实例或镜像并替换旧实例来交付变更，而非不断在原实例上原地修改的部署方式。它减少环境漂移并利于回滚，但业务持久数据与外部状态仍须独立管理。','发布新的服务镜像，验证新实例后切换流量，旧实例保留至确认安全再回收。','不可变针对被管理的运行单元；数据库数据并不因此不能修改。','把用户上传文件写进可随时替换的容器层，却没有外部持久存储。','回滚镜像为何仍可能失败？','数据库结构或消息格式已变化，旧代码可能不再兼容，需扩展收缩迁移和状态兼容策略配合。',[src('AWS Well-Architected：不可变基础设施','https://docs.aws.amazon.com/wellarchitected/latest/reliability-pillar/rel_tracking_change_management_immutable_infrastructure.html')],2,3,2),
s('canary-release','金丝雀发布','Canary Release',['Canary Deployment'], '先让新版本承接有限比例或特定群体流量，观察质量信号后再扩大范围的渐进发布方式。它限制初期影响范围，但需要代表性样本、明确阈值和可靠停止或回退机制。','先把5%读流量导向新版本，比较错误率与延迟后逐步扩到全部。','蓝绿部署强调两套环境切换；金丝雀强调小范围验证并扩大，可以组合实施。','只看总平均指标，忽略少量新版本流量已显著恶化。','低流量服务怎样做金丝雀验证？','延长观察、选择代表性场景和受控合成请求，明确统计置信与风险，不能用几次成功请求草率放量。',[src('Google SRE Workbook：金丝雀发布','https://sre.google/workbook/canarying-releases/')],2,3,2),
s('distributed-trace','分布式追踪','Distributed Tracing',['Trace','Span'], '用关联上下文把一次逻辑操作经过多个服务与组件的工作片段连接起来的观测方法，追踪由多个span及其因果关系组成。采样、异步边界与上下文传播决定能否还原实际链路。','一次导入请求产生API、文件解析、数据库写入等span，按同一追踪标识关联。','日志记录离散事件；追踪强调工作片段的结构与因果关系，二者可通过标识关联。','只记录trace_id却不传播上下文，跨服务链路因此断裂。','为什么不能把所有输入都塞进span属性？','敏感数据泄露、高基数和体积会增加风险与成本，应只记录诊断必需且经过治理的字段。',[src('OpenTelemetry：Traces','https://opentelemetry.io/docs/concepts/signals/traces/')],2,3,3),
s('health-probe','健康探针','Health Probe',['Liveness Probe','Readiness Probe','Startup Probe'], '用明确检查区分进程是否需重启、是否可接收流量及是否仍处于启动阶段的机制。不同探针失败后的动作不同，配置应反映恢复策略，避免依赖短暂波动引起重启或流量震荡。','启动慢的服务先由startup检查保护，准备就绪后才接入流量，真正僵死时再触发生存检查恢复。','存活表示是否应重启；就绪表示是否应接流量，不能把两者机械使用相同深度检查。','把全部下游依赖纳入存活检查，依赖故障时导致所有实例循环重启。','数据库短暂故障时探针应如何设计？','结合业务降级策略决定就绪状态，存活检查应避免因外部故障无益重启，同时配置阈值与恢复滞后。',[src('Kubernetes：容器探针','https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/#container-probes')],2,3,3),
]},
{id:'security',name:'身份、密码与应用安全术语',description:'安全边界、攻击类别、凭据及密码学概念。',rows:[
s('authentication','身份认证','Authentication',['AuthN'], '验证请求方是否具有其声称身份的证据的过程，可使用口令、持有设备、生物特征或多因素组合。认证结果的可信程度取决于凭据保护、协议、防重放和恢复流程，而非仅登录表单是否通过。','服务验证口令与一次性验证码后建立带有限有效期的登录会话。','认证回答“你是谁”；授权回答“你是否能执行该操作”，两者必须分别判断。','只在登录时认证，敏感操作和失窃会话却没有额外控制。','密码重置为何属于认证安全边界？','能重置凭据的人实际上可接管身份，因此找回渠道和令牌的验证、时效及单次使用同样关键。',[owasp('Authentication')],1,2,3),
s('authorization','访问授权','Authorization',['AuthZ'], '依据已确认的主体、目标资源、动作及上下文判断是否允许访问的决策过程，必须在可信执行位置对每次请求生效。未登录和已登录但无权是不同状态，猜不到资源编号也不能替代授权。','读取订单前检查订单所属租户和当前用户权限，而不只检查令牌有效。','身份认证不能推出访问任意对象的权限；资源归属也是授权规则的一部分。','前端隐藏按钮后认为后端接口不需要再次检查权限。','批量导出接口为何尤其容易越权？','若只检查入口权限却不逐资源或按租户过滤，可能把其他主体数据混入结果；计数、附件也须遵守同一边界。',[owasp('Authorization')],1,2,3),
s('rbac','基于角色的访问控制','Role-Based Access Control',['RBAC'], '把权限关联到角色，再把用户或主体分配到角色的访问控制模型，适合表达相对稳定的岗位职责。角色体系仍需考虑作用范围、职责分离和资源归属，不能仅凭一个管理员字符串覆盖所有租户。','客服角色可查看工单，财务角色可处理退款，不同租户分别授予。','角色是权限分组；属性模型按主体和资源等属性计算规则，复杂系统可组合两者。','角色无限细分到每个对象状态，导致角色爆炸和难以审计。','如何表达“经理只能审批本部门申请”？','在角色权限外加入部门范围或资源关系校验，明确角色生效的组织边界。',[src('NIST：RBAC研究','https://csrc.nist.gov/projects/role-based-access-control'),owasp('Authorization')],2,3,3),
s('abac','基于属性的访问控制','Attribute-Based Access Control',['ABAC'], '根据主体、资源、动作和环境的属性及策略计算访问许可的模型，可表达时间、组织归属与数据敏感级别等条件。属性来源的可信性和更新一致性决定策略是否可靠，复杂规则也需要可解释与测试。','要求用户部门与文档部门相同且文档密级不高于用户许可级别。','ABAC侧重属性规则；RBAC侧重角色分配，二者并不互斥。','直接信任客户端提交的department或isAdmin属性作为授权依据。','规则引擎不可用时默认怎样处理？','按威胁模型采用明确的安全失败策略，敏感操作通常拒绝并记录；同时设计缓存有效期与紧急恢复机制。',[src('NIST SP 800-162：ABAC','https://csrc.nist.gov/pubs/sp/800/162/upd2/final')],2,3,2),
s('least-privilege','最小权限原则','Principle of Least Privilege',['PoLP'], '只给主体完成明确任务所必需的最少权限，并把权限限定在合适资源、动作与时间范围内的安全设计原则。它需要持续审计与撤销流程，不是首次创建账户时设一次权限就结束。','报表服务使用只读数据库账户，不能修改表或访问无关租户资料。','最小权限不是一律不给权限，而是使授权与实际职责相匹配并能被审查。','所有服务共用数据库超级用户，期待仅靠代码自觉避免误操作。','临时运维权限如何符合该原则？','按需审批并限时授予，记录使用过程，结束后自动回收，同时保留紧急访问的可审计流程。',[owasp('Authorization'),src('NIST：最小权限定义','https://csrc.nist.gov/glossary/term/least_privilege')],1,2,3),
s('zero-trust','零信任架构','Zero Trust Architecture',['ZTA','Zero Trust'], '不因网络位置或设备归属就自动授予隐含信任，而对访问主体、设备、资源及上下文持续执行明确策略的架构思路。它强调逐次授权和最小访问，不是购买某个产品即可获得的单一功能。','来自公司内网的设备访问敏感服务，仍需身份、设备状态和资源权限检查。','零信任不是完全不使用内网隔离，而是不把“在内网”当成充分的信任证据。','声称部署VPN后已经实现零信任，所有内部请求仍无鉴权。','持续验证是否要求每次都让用户输入密码？','不一定，可使用短期凭据、设备与会话风险信号动态决策，交互重认证按风险触发。',[src('NIST SP 800-207：零信任架构','https://csrc.nist.gov/pubs/sp/800/207/final')],2,3,2),
s('threat-model','威胁建模','Threat Modeling',[], '在设计和变更时系统识别资产、信任边界、潜在威胁与防护措施的方法，目的是把风险转成可检验的设计决策。它结合具体部署和攻击者能力，不是泛泛列举所有漏洞名词。','分析文件上传流程中谁能上传、文件在哪里解析、解析器权限及结果由谁读取。','渗透测试检查具体实现；威胁建模可在编码前发现结构性风险，两者互补。','只画数据流图，却没有记录假设、缓解措施和验证责任。','需求变化后为什么要更新模型？','新增第三方接口、数据类型或部署边界会改变可达路径与信任假设，原有措施可能覆盖不足。',[owasp('Threat_Modeling')],2,3,2),
s('attack-surface','攻击面','Attack Surface',[], '系统对潜在攻击者暴露的入口、可操作功能和可利用交互的集合，包括网络接口、文件解析、依赖和管理通道等。减少不必要暴露有助于降低风险，但入口少不等于剩余入口安全。','把调试接口限制在受控网络并关闭不用的上传格式，缩小可触达功能范围。','漏洞是某个缺陷；攻击面描述攻击者可能接触和影响系统的范围。','只统计公网端口，忽视导入文件、供应链与内部管理接口。','新增长期未使用的依赖为什么也可能扩大风险？','它可能引入解析器、安装脚本或传递依赖等执行路径，需评估真实加载和运行边界再决定保留。',[owasp('Attack_Surface_Analysis')],1,2,2),
s('sql-injection','SQL注入','SQL Injection',['SQLi'], '不可信输入改变了原本预期SQL语句结构或语义的漏洞类别，常见于把数据直接拼入查询。参数化能分离值与语法，但表名、排序字段等动态结构还需使用受控映射等办法。','把用户搜索词作为绑定参数传给查询，而不是插到SQL引号中。','输入校验有帮助，但不能替代正确参数化；转义规则也依数据库和上下文变化。','以为使用ORM后任何原生查询或动态排序拼接都天然安全。','ORDER BY列名能直接用值参数替代吗？','通常不能作为普通值参数绑定，应把用户选项映射到预定义、可接受的标识符或完整排序表达式。',[owasp('SQL_Injection_Prevention')],1,3,3),
s('xss','跨站脚本','Cross-Site Scripting',['XSS'], '不可信内容以可执行脚本或危险浏览器上下文被解释的漏洞类别，可能来自持久内容、响应反射或客户端DOM操作。防护需按输出上下文编码，允许富文本时另用可靠净化策略。','笔记内容先按纯文本渲染；确需HTML时用维护良好的净化器去除危险结构。','HTML文本、属性、URL和JavaScript上下文有不同编码规则，不能一个转义函数包办。','只过滤script标签，就认为事件处理属性和危险URL也已解决。','Markdown渲染为何仍需审查XSS风险？','解析器可能允许原始HTML或危险链接，渲染后的DOM与属性才是浏览器执行边界，需明确允许策略。',[owasp('Cross_Site_Scripting_Prevention')],1,3,3),
s('csrf','跨站请求伪造','Cross-Site Request Forgery',['CSRF'], '攻击者诱使用户浏览器利用已存在的环境凭据向目标服务发送非本意操作的攻击类别，常见风险来自自动携带的会话Cookie。防护通常结合令牌、来源检查与适当Cookie策略。','修改邮箱接口校验与会话关联的CSRF令牌，而不只检查Cookie登录状态。','CORS主要约束脚本读响应，并不保证跨站请求不会被发送或产生副作用。','认为接口只接受POST就自动免疫CSRF。','SameSite能作为唯一防线吗？','需结合浏览器兼容、站点与源的差别以及业务跳转要求评估，敏感操作通常还需令牌或来源等适当验证。',[owasp('Cross-Site_Request_Forgery_Prevention')],2,3,3),
s('ssrf','服务器端请求伪造','Server-Side Request Forgery',['SSRF'], '攻击者影响服务器发起的网络请求，使其访问原本不应可达的目标或协议的漏洞类别。风险取决于服务器网络位置、凭据和解析行为，URL表面校验不能替代目标与网络边界控制。','只允许下载指定可信域的资料，并限制重定向及实际解析地址的访问范围。','浏览器跨域请求是客户端行为；SSRF利用服务器自身可达能力，影响范围可能更深。','只禁止字符串localhost，却忽略地址变体、DNS变化和重定向。','为什么需要控制重定向后的目标？','初始URL合规不代表后续位置仍合规，应对每次跳转按同一策略验证或禁用重定向。',[owasp('Server_Side_Request_Forgery_Prevention')],2,3,3),
s('jwt','JSON Web令牌','JSON Web Token',['JWT'], '用JSON声明承载身份或其他信息并按JOSE规范编码的令牌形式，可使用签名、消息认证或加密等方式保护。仅能解码载荷不代表已经验证，是否保密也取决于使用的是何种保护形式。','API验证令牌签名、预期发行者、受众和有效时间后才信任相应声明。','常见签名JWT的载荷可被读取；Base64url编码不提供加密保密性。','直接解码JWT取userId作为已认证身份，或根据不可信alg字段任意切换验证方式。','撤销未过期JWT需要考虑什么？','短有效期、令牌版本、会话撤销列表或在线状态等方案有不同成本，不能只删除客户端本地副本。',[rfc(7519),rfc(8725)],2,3,3),
s('oauth','OAuth授权框架','OAuth 2.0 Authorization Framework',['OAuth','OAuth 2.0'], '让资源所有者通过授权服务器向客户端授予有限资源访问权限的框架，使用访问令牌及规定授权流程。它主要处理委托授权，不自动定义完整用户身份认证信息或任意令牌格式。','用户允许第三方日历应用读取日程，客户端取得限定范围的访问令牌。','OAuth不是登录身份协议的完整替代；OIDC在其上规定身份层语义。','把任意access_token当成可直接向所有业务证明用户身份的ID Token。','授权码流程为什么要结合PKCE？','PKCE把授权码交换关联到发起客户端的秘密验证材料，降低授权码被截获或注入后被滥用的风险。',[rfc(6749),rfc(7636),rfc(9700)],2,3,2),
s('oidc','OpenID连接','OpenID Connect',['OIDC'], '建立在OAuth 2.0之上的身份层协议，规定ID Token等信息以表达用户认证事件与身份声明。客户端必须验证发行者、受众、签名及相关流程参数，不能因拿到JSON声明就盲目信任。','学习站使用外部身份提供商登录，客户端验证ID Token后建立本站会话。','ID Token面向客户端确认认证；Access Token用于调用资源服务器，两者用途不同。','把ID Token发送给任意API并假定它就是该API的访问授权凭据。','nonce通常用于什么？','把认证响应关联到发起的请求并降低重放风险，具体是否必须及如何验证应遵循所用流程。',[src('OpenID Connect Core 1.0','https://openid.net/specs/openid-connect-core-1_0.html')],2,3,2),
s('mac','消息认证码','Message Authentication Code',['MAC'], '使用共享秘密密钥对消息计算认证值的密码学机制，用于让持钥方检测未经授权的修改并确认消息来自某个持钥者。它不自动加密消息，也不区分共享同一密钥的不同发送方。','服务间使用约定MAC方案认证消息，接收方重新计算并安全比较认证值。','数字签名使用非对称密钥并可公开验证；MAC通常要求验证者也持有生成能力。','把普通无密钥哈希称为能证明发送者身份的消息认证码。','MAC本身能防重放吗？','不能，应把受保护的序号、时间窗或随机挑战纳入协议并记录必要状态。',[src('NIST：消息认证码术语','https://csrc.nist.gov/glossary/term/message_authentication_code'),rfc(2104)],2,3,2),
s('hmac','基于哈希的消息认证码','Keyed-Hash Message Authentication Code',['HMAC'], '通过规定的内外层密钥处理与哈希组合构造消息认证码的机制，安全性依赖底层哈希选择、密钥和协议使用方式。它不是简单把密钥与消息拼接后做一次哈希的随意替代写法。','Webhook把完整原始请求体与受保护元信息纳入HMAC，服务端按相同字节规则验证。','HMAC使用哈希构造认证码；口令存储应使用专门口令派生方案，不能只靠快速HMAC。','发送端签原始字节、接收端先重新排版JSON，造成验证对象不一致。','比较认证码为什么要注意时间行为？','逐字节提前返回可能泄漏匹配前缀，使用可靠库提供的恒定时间比较并同时验证长度和编码。',[rfc(2104)],2,3,2),
s('digital-signature','数字签名','Digital Signature',[], '用私钥对消息相关数据生成签名、由公钥验证的非对称密码机制，可验证完整性和对应私钥的持有关系。公钥与真实主体的关联仍需可信分发或证书，签名本身通常不提供内容保密。','软件发布者签署版本清单，使用者用可信公钥验证下载包是否与声明一致。','加密保护可读性；签名保护真实性与完整性，不能把私钥签名称作“私钥加密”来泛化解释全部算法。','从同一不可信下载页面取得包和公钥，就认为身份链已独立验证。','签名有效是否证明程序没有漏洞？','不是，只证明内容符合所信任密钥的签署结果；安全审查、来源信任和漏洞管理仍需单独进行。',[src('NIST FIPS 186-5：数字签名标准','https://csrc.nist.gov/pubs/fips/186-5/final')],2,3,2),
s('cryptographic-hash','密码学哈希','Cryptographic Hash Function',['Hash'], '把任意长度输入映射为固定长度摘要的密码学函数，设计上要求满足相应抗原像、抗第二原像和抗碰撞性质。有限摘要必然存在碰撞，实际安全关注在可行计算成本下难以找到所需碰撞或原像。','校验下载文件的摘要可发现与预期内容不同，但预期摘要也要从可信渠道取得。','编码可逆，哈希通常不可逆；无密钥哈希不能独立证明是谁生成内容。','把MD5仍有快速计算能力误当成适合所有安全完整性场景。','哈希值相同是否数学上证明文件必定相同？','不是严格证明，但使用合适安全算法时可把偶然或恶意碰撞风险降低到可接受范围，仍需匹配威胁模型。',[src('NIST FIPS 180-4：安全哈希','https://csrc.nist.gov/pubs/fips/180-4/upd1/final')],1,3,3),
s('salt','口令盐值','Password Salt',['Salt'], '在口令派生处理中为每个口令记录使用的独立随机或足够唯一输入，使相同口令不易产生相同存储结果并降低预计算攻击收益。盐通常可与派生结果一起存储，其作用并不依赖作为秘密保管。','两个用户密码相同，但各自随机盐不同，保存的派生结果也不同。','盐通常公开；pepper等额外秘密需独立管理，二者不能当成同一种东西。','所有账户共用一个固定盐，还宣称能阻止跨账户复用预计算。','有盐后能直接用快速SHA-256存密码吗？','仍不合适，应使用专门的口令派生方案和适当成本参数，使离线猜测需要较高资源。',[owasp('Password_Storage')],1,2,3),
s('kdf','密钥派生函数','Key Derivation Function',['KDF'], '从输入密钥材料按规定上下文与参数派生所需密钥的密码机制类别，不同KDF针对口令强化或高熵密钥扩展等不同需求。不能把所有KDF都当作刻意计算缓慢的密码存储算法。','使用HKDF从握手得到的高熵秘密派生方向不同的会话密钥；口令存储则用相应口令KDF。','HKDF适合密钥提取扩展；Argon2等口令强化方案针对低熵口令离线猜测，两者用途不同。','用一次快速哈希扩展普通用户口令，误以为已抵御离线穷举。','派生不同用途密钥为什么要有上下文分离？','明确用途标签可减少同一输出被跨协议或跨方向误用造成的风险，应遵循协议规定而非随意拼接。',[rfc(5869),rfc(9106)],2,3,2),
s('aead','带关联数据的认证加密','Authenticated Encryption with Associated Data',['AEAD'], '同时保护明文保密性与完整性，并认证无需加密的关联数据的密码接口形式。密钥、nonce和消息组合须满足算法要求，认证失败时不能把未经验证的明文继续当可信内容使用。','把消息体加密，同时把协议版本和记录类型作为关联数据参与认证。','关联数据不被隐藏但会被认证；AEAD不是单独加密后忽略完整性校验的方案。','在要求nonce不重复的算法中同一密钥下反复使用相同nonce。','为什么协议头也可放进关联数据？','头部可保持可路由或可解释，同时防止攻击者无痕更改其含义；收发双方必须使用一致字节表示。',[rfc(5116)],2,3,2),
s('pki','公钥基础设施','Public Key Infrastructure',['PKI'], '用于把公钥与主体身份关联并管理签发、验证、撤销和信任关系的一整套制度与技术设施，常通过证书及信任锚实现。可信链有效不等于证书适用于任意域名、用途或当前时间。','浏览器沿证书链验证到信任锚，并检查服务器证书的主机名、有效期和用途。','证书是其中一种凭据；PKI还包括治理、密钥保护和生命周期流程。','只验证证书签名，不检查主机名或把自签证书一概当作密码学无效。','证书续期为什么还要保护旧私钥和部署流程？','身份保证依赖私钥不泄露和正确端点使用，新证书不能自动清除已泄露密钥造成的风险。',[rfc(5280)],2,3,2),
s('forward-secrecy','前向保密','Forward Secrecy',['FS','Perfect Forward Secrecy','PFS'], '在满足协议与密钥销毁假设下，即使长期身份密钥日后泄露，也不应据此恢复以往会话密钥的安全性质。通常依靠临时密钥交换而非长期秘密直接决定所有历史会话。','会话使用临时密钥交换并清除临时秘密，日后证书私钥泄露不应单独解开旧流量。','前向保密保护历史会话，不等同受感染端点恢复后的未来会话安全。','以为启用HTTPS就能在所有协议模式和端点泄露情形下保护全部历史内容。','端点直接记录了明文还受该性质保护吗？','不会，前向保密针对密钥泄露后对已录制密文的恢复能力，无法撤回被端点日志保存的明文。',[rfc(8446)],2,3,2),
s('sbom','软件物料清单','Software Bill of Materials',['SBOM'], '描述软件组成与依赖关系的结构化清单，用于识别包、版本、来源及相关组件，支持供应链追踪和漏洞响应。它提供可分析的透明度，不能独自证明组件可信或运行环境确实使用了所有列出内容。','发布构建生成SBOM，漏洞公告出现时定位哪些版本包含相关依赖。','锁文件服务可复现依赖解析；SBOM面向组件清单交换，覆盖范围与粒度可能不同。','把已有SBOM当作已完成漏洞修复和许可证合规评估。','为什么需要让SBOM对应具体构建产物？','源码依赖与打包实际内容可能不同，必须标识构建版本、生成时间及产物关联，才能准确判断影响。',[src('CISA：SBOM资料','https://www.cisa.gov/sbom')],2,3,2),
]},
{id:'distributed',name:'分布式系统术语',description:'副本、故障、提交协议与可靠消息的语义边界。',rows:[
s('consensus','共识','Consensus',[], '分布式参与者在故障模型与协议假设下对某个值或有序决策取得一致的过程，通常区分安全性与活性。共识解决协同决策问题，不自动消除网络延迟、业务错误或所有节点失联。','多个配置节点对下一条配置变更达成一致后再向客户端确认提交。','广播让消息被发送；共识还需要保证冲突决定不会都成为有效结果。','把“多数节点最终收到相同消息”当作完整共识协议。','安全性与活性各意味着什么？','安全性要求不会产生互相矛盾的有效决定；活性关心在适当故障和时序条件下最终能够继续作出决定。',[src('Raft原作者论文','https://raft.github.io/raft.pdf')],3,3,2),
s('raft','Raft协议','Raft',['Raft consensus algorithm'], '以任期、领导者选举、日志复制和提交规则组织复制状态机的共识算法，目的是在部分节点故障时保持一致的有序日志。Raft是算法名称，不应为它杜撰正式缩写展开。','五节点Raft集群在满足协议条件时可容忍两个节点失效，并由多数节点提交新日志。','Raft不是任意主从复制的别名；选举限制、日志匹配和提交条件是其安全性组成。','认为领导者把日志写到自己磁盘就已经对集群提交。','新领导者如何避免随意丢弃已提交日志？','选举和日志新旧比较限制可当选者，配合多数派交集和日志复制规则维持已提交前缀安全。',[src('Raft原作者论文','https://raft.github.io/raft.pdf'),src('etcd：Raft与一致性保证','https://etcd.io/docs/v3.6/learning/api_guarantees/')],3,4,2),
s('quorum','法定人数集合','Quorum',['多数派集合'], '分布式协议中足以完成某类操作的参与者集合，常通过集合交集限制互相冲突的决定。多数派是常见构造，但法定集合的规模与交集要求必须结合协议和成员变更规则说明。','五个投票节点中任意三个构成多数派，不同多数派至少共享一个节点。','“读写节点数之和大于副本数”只给出交集条件，不独自证明完整线性一致性。','仅记住R+W>N公式而忽略版本选择、失败处理和并发写规则。','更改成员数量时为什么不能直接各用各的多数派？','新旧配置的决定集合可能不相交，需要联合配置或规定的安全重配置过程避免两个合法领导集。',[src('etcd：集群重配置设计','https://etcd.io/docs/v3.6/op-guide/runtime-reconf-design/')],3,4,2),
s('linearizability','线性一致性','Linearizability',[], '要求每个操作看起来在调用与响应之间的某一瞬间原子生效，并尊重已完成操作的真实时间先后关系的一致性性质。它针对外部操作历史，不意味着实现只有一份副本或零延迟。','写入新配置返回成功后才发起的线性一致读取必须看见该写入或更晚的有效状态。','最终一致允许暂时旧读；可串行化描述事务顺序等价，未必单独包含相同的真实时间要求。','把服务器之间时钟完全同步当作线性一致性成立的必要充分条件。','客户端超时能推断写入没有生效吗？','不能，操作可能已经生效但响应丢失；应结合请求身份和查询协议消除不确定结果。',[src('etcd：API保证','https://etcd.io/docs/v3.6/learning/api_guarantees/')],3,4,2),
s('eventual-consistency','最终一致性','Eventual Consistency',[], '允许副本暂时不同，但在不再产生新更新且通信与修复等条件满足后，系统最终使副本收敛的一致性承诺。它需要明确冲突解决规则与收敛前提，不能只用“过一会就一样”代替保证。','读副本在复制延迟期间返回旧资料，追上日志后获得新的提交值。','最终一致不保证读己之写、单调读或有界陈旧，这些是额外会话或时间保证。','不给失败重试和修复机制，却把长期不一致称为最终一致。','如何让用户更新后立即看到自己的结果？','可路由到满足所需日志位置的副本、携带版本令牌或暂时读主库，按业务选择会话一致性策略。',[src('Amazon Dynamo原作者论文','https://www.allthingsdistributed.com/files/amazon-dynamo-sosp2007.pdf')],2,3,3),
s('cap','CAP定理','Consistency, Availability, Partition Tolerance',['CAP'], '在存在网络分区的特定分布式模型中，不能同时保证线性一致性和对每个非故障节点请求都成功响应的可用性。它是有明确假设的限制，不是任意系统永久从三个功能中勾选两个。','两组副本无法互通时，系统可拒绝一侧写入以保护一致性，或接受并后续处理冲突。','CAP可用性不是常规SLA百分比；其一致性也不是ACID中的业务不变量含义。','把单机数据库标成CA就认为分布式故障问题已解决。','没有网络分区时还要不要考虑一致性与延迟？','需要。CAP并未消除正常通信期间的副本同步代价和延迟权衡，应另外分析实际服务目标。',[src('Gilbert与Lynch：Perspectives on the CAP Theorem','https://groups.csail.mit.edu/tds/papers/Gilbert/Brewer2.pdf')],3,3,3),
s('network-partition','网络分区','Network Partition',[], '分布式节点之间部分通信链路不可达或严重延迟，使仍在运行的节点被划分成无法可靠互通的子集的故障情形。节点本身可能健康，因此单凭本地存活检查不能辨认远端是否已停止。','两个机房的链路断开，两边应用都能接收本地流量但不能交换副本更新。','数据分区用于拆分数据集合；网络分区描述通信故障，中文都叫分区却含义不同。','把超时当成对方一定宕机并立即允许双方同时当主。','为什么故障检测通常只能怀疑而不能绝对证明宕机？','消息延迟或丢失可与节点停止表现相同，协议必须在这种不确定性下保护安全并规定恢复行为。',[src('etcd：故障模式','https://etcd.io/docs/v3.6/op-guide/failures/')],2,3,2),
s('replication','数据复制','Data Replication',['Replication'], '把数据库或状态变更传播到多个节点以获得容错、读取扩展或地域接近性的机制，可采用同步或异步方式。副本并非天然同时最新，故障切换与一致性取决于确认和应用规则。','主节点提交日志后从节点持续接收并重放，使部分读取转移到从节点。','复制同步多个运行副本；备份保留独立恢复点，误删也可能迅速复制到所有在线副本。','用多个实时副本替代离线或隔离备份。','异步复制下主库故障可能丢什么？','已向客户端确认但尚未复制到新主的修改可能丢失，需依据确认策略与实际复制位置评估RPO。',[pg('different-replication-solutions'),pg('warm-standby')],2,3,3),
s('sharding','分片','Sharding',['水平分片'], '按分片键或其他规则把一个逻辑数据集拆到多个存储单元的扩展方式，使单节点不必容纳全部数据。路由、再均衡和跨分片操作成为额外系统职责，热点仍可能集中在少数分片。','按租户标识路由业务记录到不同分片，单租户查询尽量在一个分片完成。','复制保留相同数据的副本；分片把不同数据分散，两者可同时使用。','只增加分片数量而不分析分片键分布与跨片访问。','分片键为什么应尽量稳定？','键变化可能要求迁移记录并更新路由或相关索引，频繁变化会放大一致性与运维复杂度。',[src('MongoDB：分片','https://www.mongodb.com/docs/manual/sharding/')],2,3,3),
s('leader-election','领导者选举','Leader Election',[], '多个参与者依据约定协议选择具有协调权限的节点或持有者的过程，用于限定某些顺序化工作。选出谁、权限何时生效以及旧持有者如何失去权限必须共同设计，不能只发一条“我是主”。','多个调度实例通过一致性存储竞争租约，选定一个实例分派定时任务。','选举确定协调者；外部资源是否拒绝旧协调者的迟到操作还需要额外保护。','以为选出了新主，旧主即使仍运行也不可能写数据。','为何选举后仍可能需要fencing？','暂停的旧主恢复时可能不知道已失权，资源端校验递增令牌才能拒绝其迟到请求。',[src('etcd：并发与选举API','https://etcd.io/docs/v3.6/dev-guide/api_concurrency_reference_v3/')],3,3,2),
s('split-brain','脑裂','Split Brain',[], '原本要求单一权威的系统在通信或故障切换后出现多个节点同时自认为有权提供冲突写入或控制的状态。危险不只在节点数量，而在外部资源可能接受多个权威的互斥决定。','旧调度主机与协调集群断开但还能访问设备，新主也开始向同一设备发送控制命令。','多主系统是有意设计的并发权威模型；脑裂是违反预期权威约束的故障。','仅在新主写一个布尔标记，就假设已停止旧主执行。','如何减少脑裂对外部资源的损害？','使用多数派授权、隔离故障节点及资源端fencing校验，结合超时与租约而非只依赖本地角色变量。',[src('etcd：故障模式','https://etcd.io/docs/v3.6/op-guide/failures/')],3,3,2),
s('fencing','隔离令牌','Fencing Token',['Fencing'], '为每次有效权限授予分配单调递增的代次，资源端拒绝旧代次请求的保护机制。它把“是否仍有权操作”的判断放到最终接受副作用的位置，用于阻止过期锁持有者的迟到写入。','文件服务记录已接受的最大令牌，旧主携带更小令牌恢复写入时被拒绝。','租约限制持有期限；fencing校验请求代次，二者处理的故障边界不同。','生成递增令牌却不让被保护资源校验，仍认为已经完成隔离。','随机UUID可以直接作为fencing令牌吗？','仅唯一通常不够，资源需要判断新旧代次；可使用具有明确顺序和授权语义的编号及校验规则。',[src('Martin Fowler：Generation Clock模式','https://martinfowler.com/articles/patterns-of-distributed-systems/generation-clock.html')],3,4,2),
s('lease','租约','Lease',[], '在有限时间或有效期条件内授予某种资源、领导权或会话关联权限的机制，持有者需续约维持。失效判断依赖协议和时间假设，进程暂停或网络延迟可使本地认知落后于真实授权状态。','服务注册记录绑定租约，续约停止后注册信息由协调存储自动清理。','普通锁可能无自动期限；租约强调有界有效性，但不单独保证外部副作用不会迟到。','只按本地计时推断权限仍有效，忽略停顿、时钟与请求延迟。','租约到期后为什么还要考虑旧请求？','旧持有者可能已发出或稍后恢复发送请求，最终资源应通过代次等机制拒绝过期授权。',[src('etcd：Lease API','https://etcd.io/docs/v3.6/learning/api/')],3,3,2),
s('idempotency','幂等性','Idempotency',[], '同一逻辑操作执行一次和重复执行多次对所关注状态具有相同最终效果的性质，适用于安全重试设计。它不要求每次响应完全相同，也不意味着操作没有任何日志、时间等附带变化。','使用同一请求编号重复提交订单时，服务返回同一订单而不是再次创建。','幂等不同于去重实现；去重键、唯一约束和状态机是实现幂等语义的常见工具。','只把POST改名PUT，却未实现重复请求下的原子约束。','相同幂等键携带不同参数应怎样处理？','应校验请求摘要或关键参数并拒绝冲突复用，不能悄悄返回与新参数无关的旧结果。',[src('AWS Builders Library：幂等API','https://aws.amazon.com/builders-library/making-retries-safe-with-idempotent-APIs/'),rfc(9110)],2,3,3),
s('deduplication','消息去重','Message Deduplication',['Deduplication'], '识别多次交付是否属于同一逻辑消息，并在规定窗口与范围内抑制重复处理的机制。它需要稳定身份、原子记录和保留策略，去重窗口以外的旧消息仍可能再次出现。','消费端用事件编号建立唯一处理记录，并与业务更新在同一事务内提交。','仅对消息正文做哈希可能合并本应独立的相同业务事件；身份设计需表达真实事件。','先查去重表不存在，再分开执行业务与登记，留下并发及崩溃窗口。','为什么去重记录要有保留策略？','无限保留增加成本，过早清理则可能重放旧消息；应依据重试、重放和合规需求界定窗口。',[src('RabbitMQ：可靠性指南','https://www.rabbitmq.com/docs/reliability'),src('AWS Builders Library：幂等API','https://aws.amazon.com/builders-library/making-retries-safe-with-idempotent-APIs/')],2,3,3),
s('at-least-once','至少一次交付','At-Least-Once Delivery',[], '消息系统在约定持久化、重试和故障假设下力求每条有效消息被交付一或多次的语义，允许重复。只有把确认、重试和业务处理放在明确边界内，才能讨论实际端到端保证。','消费者提交业务后尚未确认即断线，消息再次交付给另一个消费者。','至少一次不等于必然恰好处理一次；副作用重复需要幂等或去重防护。','收到消息就立刻确认，然后假设进程崩溃后业务也不会丢。','消费者应在什么时候确认？','通常在目标业务结果已可靠提交后确认，并处理提交成功但确认丢失导致的再次投递。',[src('RabbitMQ：消费者确认与发布确认','https://www.rabbitmq.com/docs/confirms')],2,3,3),
s('at-most-once','至多一次交付','At-Most-Once Delivery',[], '在定义的交付范围内不重复交付同一消息、但允许消息丢失的语义。减少重试或提前确认可实现类似效果，却必须接受故障窗口中的遗漏，不能把“不重复”误作“必达”。','消费端自动确认后崩溃，已经从队列移走的消息可能没有完成业务处理。','至多一次限制重复；至少一次关注不遗漏但允许重复，二者风险取舍不同。','为了避免重复直接禁用一切重试，却继续承诺业务不会丢失。','哪些业务可能接受至多一次？','允许采样或下一条状态覆盖旧状态的非关键遥测可能接受，但需明确丢失容忍度，不能用于未经评估的扣款任务。',[src('RabbitMQ：消费者确认与发布确认','https://www.rabbitmq.com/docs/confirms')],2,3,2),
s('exactly-once','恰好一次处理语义','Exactly-Once Processing Semantics',['Exactly-Once Semantics','EOS'], '在明确定义的事务、输入与输出边界内，使故障恢复和重试后的可观察结果等价于每个逻辑事件处理一次的保证。它通常依靠事务与幂等协议，不意味着网络实际只发送一次报文。','流处理把消费位置和输出记录在同一受支持事务中提交，避免恢复时暴露重复结果。','代理内部事务不自动覆盖外部邮件、文件或任意HTTP副作用，必须逐一划定边界。','看到框架写着exactly-once就宣称整个跨系统业务天然恰好一次。','外部支付如何纳入类似结果保证？','需支付方支持幂等身份和结果查询，并与本地状态恢复协作；不能只靠消息代理的内部事务。',[src('Apache Kafka：消息处理语义','https://kafka.apache.org/41/design/design/')],3,4,2),
s('outbox','事务发件箱','Transactional Outbox',['Outbox Pattern'], '把业务数据修改和待发送事件写入同一本地数据库事务，再由独立发布过程转发事件的可靠协作模式。它避免数据库提交后尚未发送便崩溃的丢失窗口，但发布过程仍可能重复发送。','订单事务同时写订单行和outbox行，发布器稍后把事件送入消息系统。','outbox解决本地提交与发出事件的协调，不保证所有消费者同时原子提交。','发布成功后标记状态之前崩溃，却以为该模式绝不会重复。','消费者仍需做什么？','按事件身份幂等处理或去重，并明确顺序、重放和失败事件处置，发布器也需可恢复地推进状态。',[src('Chris Richardson：Transactional Outbox','https://microservices.io/patterns/data/transactional-outbox.html')],3,3,3),
s('saga','Saga事务模式','Saga',['Saga Pattern'], '用一组本地事务及相应补偿步骤协调跨服务业务流程的模式，各步骤先独立提交，失败时通过后续业务操作纠正已发生效果。补偿不是数据库时间倒流，必须处理幂等与补偿失败。','订房成功后付款失败，流程执行取消预订并处理可能产生的取消规则。','两阶段提交追求协议范围内的原子提交；Saga允许中间状态并依赖业务补偿与隔离策略。','把补偿写成无条件删除，忽略并发更新及已经发生的不可逆现实效果。','发出邮件能被Saga真正撤回吗？','通常不能，需发送纠正通知或设计延迟副作用等业务方案，明确无法逆转的边界。',[src('Chris Richardson：Saga模式','https://microservices.io/patterns/data/saga.html')],3,4,2),
s('two-phase-commit','两阶段提交','Two-Phase Commit',['2PC'], '协调者先让参与者准备并承诺可提交，再发布最终提交或回滚决定的分布式提交协议。准备阶段后参与者可能持有资源等待决定，因此协调器故障与恢复日志会影响阻塞和可用性。','跨数据库事务先让两边prepare，全部成功后由协调者记录并发送commit。','2PC主要解决原子提交，不等于Raft等用于复制决策的共识算法，两者可在系统中配合。','认为参与者超时就可随意单方面回滚已准备事务而不破坏协议。','准备后协调者失联为什么可能阻塞？','参与者可能不知道其他节点是否已收到提交决定，需要恢复协调状态或按协议取得可靠最终决定。',[src('Oracle：分布式事务概念','https://docs.oracle.com/en/database/oracle/oracle-database/19/admin/distributed-transactions-concepts.html')],3,4,2),
s('circuit-breaker','熔断器','Circuit Breaker',['Circuit Breaker Pattern'], '根据一段时间内的故障等信号暂时阻断对不健康依赖的调用，并在受控探测后恢复的保护模式。常以关闭、打开和半开等状态表达，目标是限制持续失败造成的资源耗尽与级联故障。','支付接口持续超时后暂停大部分调用，少量探测成功再逐步恢复。','重试再次尝试单次失败；熔断按整体健康情况暂时停止一类调用，二者必须协调。','熔断打开后仍进行大量无界重试，抵消保护效果。','半开状态为什么要限制并发探测？','避免恢复中的依赖被同时涌入的大量请求再次压垮，探测结果也需按明确规则决定恢复或重新打开。',[src('Microsoft Azure：Circuit Breaker','https://learn.microsoft.com/en-us/azure/architecture/patterns/circuit-breaker')],2,3,3),
s('bulkhead','舱壁隔离','Bulkhead Isolation',['Bulkhead Pattern'], '把不同工作或依赖所用资源划分为独立且有上限的池，使一个部分拥堵或故障时不耗尽全局资源的容错模式。隔离维度可为线程、连接、队列或实例，分区过细也有成本。','慢速导出使用独立工作池，避免占满处理登录请求的线程。','熔断依据健康程度拒绝调用；舱壁通过资源边界限制相互拖累，两者可同时采用。','只分线程池却共享一个无上限任务队列或同一耗尽的数据库连接池。','资源池越多是否越好？','不是，静态划分可能导致闲置和总体利用率降低，应依据关键路径、容量与故障影响设计。',[src('Microsoft Azure：Bulkhead','https://learn.microsoft.com/en-us/azure/architecture/patterns/bulkhead')],2,3,2),
s('backpressure','背压','Backpressure',[], '下游通过需求或容量信号约束上游生产与发送速度的流量协调机制，防止缓冲和待处理任务无限增长。它需要贯穿生产、传输及消费路径，并定义无法减速时的丢弃或拒绝策略。','消费者只请求能处理的下一批元素，上游按需求发送而非持续塞入无界队列。','限流限定入口速率；背压强调从下游处理能力向上游传播压力，可以结合使用。','队列不断增长却只增加重试次数，使积压进一步扩大。','上游是不能暂停的设备数据怎么办？','需定义有界缓冲、采样、丢弃、降级或持久化策略，并明确对数据完整性与延迟的取舍。',[src('Reactive Streams规范','https://www.reactive-streams.org/')],2,3,3),
s('rate-limiting','速率限制','Rate Limiting',['限流'], '在某个时间或资源范围内限制请求、事件或工作量准入的机制，用于保护容量与分配公平性。必须明确按用户、接口、租户还是全局计数，并定义突发、排队和拒绝后的反馈。','为昂贵搜索接口按用户限制请求量，超限返回明确状态和可重试提示。','并发限制控制同时在途数量；速率限制控制单位时间准入，两者不能简单互换。','每个实例各限100次却把十实例集群说成全局只允许100次。','分布式全局限流需要考虑什么？','计数一致性、网络延迟、时钟或窗口语义、失效时放行或拒绝，以及协调服务本身的可用性和容量。',[src('Envoy：全局限流','https://www.envoyproxy.io/docs/envoy/latest/intro/arch_overview/other_features/global_rate_limiting')],2,3,3),
]},
{id:'database',name:'数据库与数据一致性术语',description:'事务、并发可见性、关系约束与查询执行。',rows:[
s('transaction','数据库事务','Database Transaction',[], '把一组数据库操作组织成具有明确开始与结束边界的工作单元，成功时提交，失败时可回滚。事务的隔离和持久性保证取决于数据库、隔离级别及配置，不是任意外部操作都被自动纳入。','转账的扣款和入账在同一事务提交，避免只完成一半的数据库状态。','事务原子性不自动覆盖发送邮件或调用支付网关等外部副作用。','在事务中发送外部通知后回滚数据库，却以为通知也随之撤销。','长事务为什么影响系统运行？','可能长时间持锁、保留旧版本并占用连接资源，扩大冲突与维护压力，应合理划分边界。',[pg('tutorial-transactions')],1,2,3),
s('acid','事务ACID性质','Atomicity, Consistency, Isolation, Durability',['ACID'], '概括事务原子性、一致性、隔离性与持久性的术语组合：关注整体提交、约束成立、并发可见性和提交后的恢复保证。各项需结合系统语义理解，不能仅凭产品宣传推定所有配置均满足同等保证。','库存事务提交后数量约束仍成立，崩溃恢复能找回已承诺持久化的提交结果。','ACID的一致性侧重数据库及业务不变量，不等于分布式副本的线性一致性。','认为数据库支持ACID就能自动识别所有业务规则。','余额不能为负应由谁保证？','使用数据库约束、条件更新与正确事务设计共同表达不变量；ACID不会凭空推断未编码的业务条件。',[pg('tutorial-transactions'),pg('wal-intro')],1,3,3),
s('mvcc','多版本并发控制','Multiversion Concurrency Control',['MVCC'], '通过保留记录的不同版本并依据事务或语句的可见性规则读取相应版本的并发控制技术。它可减少读写冲突，但写写冲突、版本回收以及事务隔离异常仍需另行处理。','一条长查询按自己的可见性规则读取旧版本，同时另一事务提交新值。','MVCC是实现技术；快照隔离或可串行化是语义保证，不能画等号。','把MVCC描述成数据库完全不使用锁。','为什么旧版本不能立即删除？','仍有活跃快照可能需要读取它们，必须判断可见性后回收，长事务因此会增加版本保留压力。',[pg('mvcc-intro'),pg('routine-vacuuming')],2,3,3),
s('wal','预写日志','Write-Ahead Logging',['WAL'], '在把数据页修改持久写入前先按规定持久化相应日志记录的恢复技术，使崩溃后能据日志重建已提交修改。它规定日志与数据写入顺序，日志刷新策略直接影响承诺的持久性。','事务提交先确保必要WAL记录到达持久存储，数据页可稍后由后台写回。','WAL是恢复机制；逻辑审计日志面向业务追踪，不能彼此直接替代。','认为数据库目录里有WAL文件就可随意单独复制主数据库文件。','为何备份需要协调日志位置？','备份页面可能来自不同时刻，需要相应日志和一致性协议恢复到可用状态，必须使用受支持的备份方式。',[pg('wal-intro'),src('SQLite：WAL','https://www.sqlite.org/wal.html')],2,3,3),
s('snapshot','数据库快照','Database Snapshot',[], '描述某个观察边界下哪些数据库版本对读取可见的规则或视图，可用于一致性读取。事务快照不必是物理复制文件，也不自动包含数据库外部文件与远程服务的状态。','导出任务在一致性快照中遍历多张表，避免部分表反映新版本而部分反映旧版本。','读取快照是可见性抽象；物理备份或存储快照是另外的实现与运维概念。','把事务中每条查询都假定会使用同一个快照。','读已提交下两条SELECT可能看到不同提交吗？','可能，PostgreSQL读已提交通常为每条语句建立新的可见性边界，而更强级别有不同规则。',[pg('transaction-iso'),pg('functions-info')],2,3,2),
s('isolation-level','事务隔离级别','Transaction Isolation Level',[], '规定并发事务可以观察哪些中间或已提交状态、以及需要避免哪些异常的语义级别。相同级别名在不同数据库中的实现和额外保证可能不同，选择时应核对实际行为。','报表希望一次事务内重复读取稳定结果，可依据产品语义选择相应隔离级别。','隔离级别不是锁粒度配置，也不是事务数量越少就天然越强。','把SQL标准最低要求当作每个数据库完全一致的实际行为。','提高到可串行化后还需处理什么？','并发事务可能因序列化冲突被中止，应用需要可安全重试整个事务，且避免重复外部副作用。',[pg('transaction-iso'),src('SQLite：隔离','https://www.sqlite.org/isolation.html')],2,3,3),
s('serializability','可串行化','Serializability',[], '要求并发事务执行产生的可观察结果等价于某个串行执行顺序的隔离性质，而不要求实现必须逐个实际执行。它约束整个事务间关系，适合保护复杂跨行不变量。','两名值班医生都想离岗的并发事务不能同时破坏“至少一人在岗”的约束。','可串行化不一定满足按真实时间排序的严格可串行化，也不等同单个请求的线性化。','认为启用可串行化后应用不再会收到冲突错误。','序列化失败时只重试最后一条SQL够吗？','通常不够，应重新执行整个事务并重新读取决策所需数据，否则仍可能使用过时前提。',[pg('transaction-iso')],3,3,3),
s('dirty-read','脏读','Dirty Read',[], '一个事务读到了另一个尚未提交事务修改的数据的并发异常，如果对方随后回滚，读到的值就从未成为合法提交结果。是否允许脏读取决于具体隔离语义而非查询是否只读。','订单查询先看到未提交的余额增加，付款判断通过后该增加又被回滚。','不可重复读读到的是不同时刻已提交的变化；脏读关键是读到了未提交修改。','把所有“查到旧数据”都叫脏读。','读已提交能解决所有并发业务错误吗？','不能，它主要阻止读到他人未提交修改，重复读取、跨行写偏斜等仍需按系统行为另行处理。',[pg('transaction-iso')],1,2,3),
s('nonrepeatable-read','不可重复读','Nonrepeatable Read',[], '同一事务重复读取同一数据时，因其他事务在两次读取之间提交了修改而获得不同值的现象。它描述可见性变化，不意味着数据库物理损坏，也不能简单靠应用缓存掩盖所有相关风险。','事务先读到商品价格100，另一事务提交调价后再次读到120。','幻读侧重条件集合新增或消失；不可重复读侧重已读取行的值发生变化。','把事务内两次查询间业务代码主动更新造成的变化也叫该异常。','此现象是否总是坏事？','不是，有些交互希望看到最新提交；关键在于业务是否需要稳定快照或原子条件检查。',[pg('transaction-iso')],1,2,3),
s('phantom-read','幻读','Phantom Read',[], '事务重复执行相同条件查询时，因其他事务提交插入、删除或影响条件匹配的修改而看到结果集合变化的现象。具体隔离级别是否防止它需查数据库语义，不能仅凭行锁推断。','先查询某时间段的预约为空，另一个事务插入后再次查询出现一条预约。','不可重复读强调已有行内容变化；幻读强调条件匹配集合变化。','认为锁住本次返回的现有行就必然锁住所有尚不存在的匹配位置。','禁止重叠预约应如何保障？','优先用能表达不变量的约束、可串行化事务或精确同步方案，并验证空结果、范围和并发插入情形。',[pg('transaction-iso'),pg('ddl-constraints')],2,3,3),
s('write-skew','写偏斜','Write Skew',[], '并发事务依据同一旧快照分别修改不同记录，各自局部检查通过，但合并后的提交结果破坏跨记录约束的异常。因为未必写同一行，简单的写写冲突检测不一定阻止它。','两名医生各看到另一人在岗，于是分别把自己的在岗记录改为否。','丢失更新通常涉及同一值的写覆盖；写偏斜可发生在不同数据行。','以为避免同一行写冲突就保证了所有业务不变量。','如何处理这个值班例子？','可使用可串行化并重试、锁定共同的协调记录，或改写模型使不变量有可被数据库强制检查的表达。',[pg('transaction-iso')],3,4,2),
s('occ','乐观并发控制','Optimistic Concurrency Control',['OCC'], '先允许事务或请求基于已读状态工作，再在提交或更新时验证该状态是否仍适用的并发控制思路。发生冲突时拒绝或重试，适合低冲突且验证边界能被明确表达的场景。','UPDATE文档时附带版本号条件，受影响行为0就提示文档已被其他人改动。','乐观并发不是完全不用数据库锁，而是业务层不预先长时间独占资源。','检查版本后再无条件更新，留下检查与写入之间的竞态窗口。','版本号校验必须与写操作怎样配合？','应在同一原子条件更新或受保护事务中完成，并同时验证业务条件与受影响行数。',[pg('sql-update'),rfc(9110)],2,3,3),
s('pessimistic-lock','悲观并发控制','Pessimistic Concurrency Control',['Pessimistic Locking'], '在读取或修改关键数据前获取适当的锁以约束其他参与者的冲突操作，并将保护持续到规定边界的控制方式。锁定范围和顺序决定正确性与并发度，也可能引入等待和死锁。','处理有限库存时先锁定库存行，再检查并减少可售数量。','悲观控制提前协调冲突；乐观控制通常在更新或提交阶段验证冲突，两者可组合使用。','把行锁拿到后再调用耗时远程接口，长时间占锁。','锁定一个库存行能保护另一个无关表的不变量吗？','只能在所有参与者遵守同一协调约定时作为保护点；否则需约束或其他事务设计覆盖全部写路径。',[pg('explicit-locking')],2,3,3),
s('database-index','数据库索引','Database Index',['Index'], '为特定访问条件维护额外查找结构以减少扫描工作量的数据库对象，可支持检索、排序或约束。它需要占用存储并随写入更新，是否使用由优化器和代价估算等因素决定。','按用户编号频繁查订单时建立相应索引，避免每次遍历全部订单。','索引不是预先保存每一种查询结果；不同结构和键顺序服务不同访问模式。','认为任何查询只要用到索引都一定比顺序扫描快。','为什么小表可能选择全表扫描？','索引访问和随机取行有额外开销，小表或大比例返回时顺序扫描可能更便宜，应看实际计划和耗时。',[pg('indexes-intro')],1,2,3),
s('composite-index','复合索引','Composite Index',['Multicolumn Index','联合索引'], '以多个列或表达式共同组成索引键的结构，用于支持特定组合过滤与排序。列顺序、比较条件和具体索引实现会影响可利用程度，不能只看查询里出现了几个索引列。','为按租户再按创建时间检索建立(tenant_id,created_at)索引。','多个单列索引不等同一个复合索引，合并索引访问与按组合键扫描的代价不同。','机械地把左前缀规则扩展到所有数据库、索引类型和优化策略。','为什么应把查询排序也纳入设计？','匹配索引顺序可能避免额外排序，但过滤选择性、范围条件与返回数量也会影响最终收益。',[pg('indexes-multicolumn'),pg('indexes-ordering')],2,3,3),
s('covering-index','覆盖索引','Covering Index',[], '某查询所需数据可由索引项提供的访问条件，可能使执行器避免访问基础表页面。能否真正仅索引扫描还受数据库可见性检查、索引类型及存储状态影响，不是索引包含列就永远零回表。','索引键加包含列覆盖列表页需要返回的少量字段。','覆盖索引描述数据覆盖条件；Index-Only Scan（仅索引扫描）是实际执行方式，二者不必始终同时成立。','把覆盖索引当作一种在任何查询中都固定成立的索引类型。','PostgreSQL为何有时仍检查堆页面？','需要确认行版本对事务可见，若可见性映射不足以证明，仍会访问堆以验证。',[pg('indexes-index-only-scans')],2,3,2),
s('selectivity','选择率','Selectivity',[], '用于描述某谓词预期匹配数据比例的查询优化概念，匹配越少通常称选择性越高。统计估算与真实数据分布可能有差异，术语中的比例方向应明确，避免“高选择率”的歧义。','唯一用户编号等值查询通常匹配极少记录，而常见状态值可能匹配大部分表。','不同值数量是列基数的一种描述；谓词选择性还取决于具体值、相关性和分布。','认为列有很多不同值就保证所有条件都高度过滤。','统计过期为什么会影响计划？','优化器可能错误估计返回行数和连接代价，选错访问路径或连接顺序；更新统计后仍需核对实际执行。',[pg('planner-stats'),pg('row-estimation-examples')],2,3,2),
s('query-plan','查询执行计划','Query Execution Plan',['Execution Plan','EXPLAIN'], '数据库将声明式查询转换为具体访问、连接、过滤和聚合等操作的执行方案，通常附带估计成本和行数。分析实际执行计划可比较估算与运行事实，但获取实际数据本身可能真正执行查询。','计划显示先索引筛选订单，再与用户表连接，而不是按SQL书写顺序逐句执行。','SQL表达想要什么；计划表达如何取得结果，二者不是相同执行步骤。','在生产直接对有副作用的语句运行EXPLAIN ANALYZE而不考虑它会执行。','看计划时为什么要比较估计行数和实际行数？','明显偏差可能说明统计、数据相关性或参数分布问题，并会放大连接与内存选择误差。',[pg('using-explain')],2,3,3),
s('primary-key','主键','Primary Key',['PK'], '关系表中被指定用于标识每条记录的键约束，通常要求各行键值唯一且不为空，并可由单列或多列组成。主键是逻辑身份选择，不必与业务展示编号或物理存储顺序完全相同。','订单以不可变编号为主键，另用可读业务流水号供用户沟通。','唯一约束可有多个；一张表通常只指定一个主键，但它可以是复合键。','默认自增键永远连续且可当作准确的业务数量统计。','为什么事务回滚后可能留下编号空洞？','序列或编号分配机制可能不回收已分配值，以避免冲突和协调代价，不能要求它天然无间断。',[pg('ddl-constraints')],1,2,3),
s('foreign-key','外键','Foreign Key',['FK'], '约束表中一组值必须引用另一组具备合适唯一性保证的键值，或按规则允许空值的关系完整性机制。删除更新时的限制或级联行为需明确配置，不等于查询时自动连接两张表。','订单的customer_id引用客户主键，防止插入指向不存在客户的订单。','外键保证引用关系；JOIN用于组合结果，即使没有外键也能执行连接查询。','认为加了外键数据库就必然自动给引用侧建好所有性能索引。','级联删除为什么要谨慎？','删除一个上层对象可能传播到大量记录，需评估业务留存、锁等待和审计要求并测试影响范围。',[pg('ddl-constraints')],1,2,3),
s('unique-constraint','唯一约束','Unique Constraint',['UNIQUE'], '要求指定列组合在表内不能出现违反唯一性规则的重复值的数据库约束，能作为并发条件下的最终一致性防线。NULL处理、排序规则和条件唯一性需依据具体数据库说明。','在(tenant_id,email)上约束唯一，使两个并发注册不能在同一租户创建相同邮箱。','先SELECT检查不存在再INSERT不能替代数据库唯一约束，因为检查与插入间可并发。','不检查数据库对NULL或大小写比较的语义就宣称“绝不会重复”。','唯一冲突应该如何反馈？','识别预期约束冲突并返回可理解的业务结果；不能把所有数据库错误都伪装成重复键。',[pg('ddl-constraints'),pg('indexes-unique')],1,2,3),
s('sql-null','SQL空值','SQL NULL',['NULL'], 'SQL中表示未知、缺失或不适用等情况的特殊标记，并非普通数字零或空字符串。其比较通常参与三值逻辑，筛选条件、聚合与唯一性行为需要按SQL及数据库实现理解。','WHERE deleted_at IS NULL查找尚未标记删除时间的记录。','空字符串是具体字符串值；NULL与任意普通值的相等比较通常得到未知而非真。','使用column = NULL筛选空值，或者忽略NOT IN集合中存在NULL的影响。','COUNT(*)与COUNT(column)在空值上有什么差异？','COUNT(*)计行数，COUNT(column)只计该表达式非NULL的行；其他聚合也需核对各自空值规则。',[pg('functions-comparison'),pg('functions-aggregate')],1,2,3),
s('database-view','数据库视图','Database View',['View'], '以命名查询向调用者呈现表状结果的数据库对象，普通视图通常保存定义而非独立保存完整结果数据。它可封装查询与访问边界，性能和可更新能力仍取决于定义及数据库规则。','把订单与客户的常用连接封装成视图，统一报表使用的列和过滤条件。','物化视图保存查询结果并需要刷新；普通视图不等于缓存。','认为把慢SQL放入普通视图就会自动获得预计算加速。','视图能作为完整安全边界吗？','可以参与权限设计，但需核对调用者或定义者权限、行级策略及函数行为，不能只靠隐藏表名。',[pg('sql-createview'),pg('rules-materializedviews')],2,3,2),
s('normalization','数据库规范化','Database Normalization',['Normalization'], '依据函数依赖等关系模型规则组织表结构以减少冗余和更新异常的设计过程。规范化强调数据语义和依赖关系，不是把所有字段机械拆成最小表，也不排除有依据的反规范化。','把部门名称从每个员工行移到部门表，避免同一部门被更新成多个不同名称。','反规范化是为特定读取或历史语义有意保留冗余，需负责一致性维护，不是任意重复字段。','只按字段数量判断范式，而不分析候选键和函数依赖。','什么时候可以有意保留订单收货地址副本？','当它表达下单时历史快照而非当前客户地址时具有独立业务意义，不能简单当作应被消除的重复。',[src('Microsoft：数据库规范化说明','https://learn.microsoft.com/en-us/office/troubleshoot/access/database-normalization-description')],2,3,2),
s('checkpoint','数据库检查点','Database Checkpoint',['Checkpoint'], '恢复系统把部分持久状态推进到已知边界、记录恢复所需位置的过程，用来限制后续恢复需要重放的范围。具体数据库中其写页、日志回收和阻塞行为不同，不能把它等同事务提交。','后台检查点逐步刷写脏页，崩溃恢复不必总是从最早日志重放。','提交确认单个事务的结果；检查点协调持久页与恢复边界，二者时间可不同。','以为检查点完成后任何相关日志都可手工删除。','SQLite长读事务为什么可能影响WAL检查点？','读者仍可能需要既有WAL内容，阻止检查点推进或截断到某些位置，日志可能持续增长。',[pg('wal-configuration'),src('SQLite：WAL检查点','https://www.sqlite.org/wal.html')],2,3,2),
]},
{id:'network',name:'网络与接口术语',description:'协议全称、缩写、报文与应用接口概念。',rows:[
s('tcp','传输控制协议','Transmission Control Protocol',['TCP'], '互联网传输层提供的面向连接、可靠且有序的字节流协议，使用序号、确认、重传和流量控制等机制管理通信。它保留字节顺序，但不保留应用每次发送的消息边界。','发送两条业务消息后，接收方一次read可能读到第一条的一部分或两条的合并数据。','可靠传输不表示业务一定执行成功；应用仍需定义请求编号、应答和重试语义。','把一次send对应一次recv当成协议保证。','应用如何从字节流恢复消息边界？','定义长度前缀、分隔符及转义规则或固定结构，并限制长度、处理拆包与多包合并。',[rfc(9293)],1,2,3),
s('udp','用户数据报协议','User Datagram Protocol',['UDP'], '互联网传输层提供的数据报协议，以独立报文承载应用数据，协议自身不保证送达、顺序、去重或拥塞控制。应用可按需要增加可靠性、安全和节流，但不能默认这些能力已存在。','实时状态上报可以接受偶发丢包，下一帧覆盖旧状态。','UDP保留数据报边界；TCP提供字节流，两者能力组合和使用代价不同。','认为UDP无连接就意味着应用无需维护任何会话或防滥用状态。','UDP应用为什么仍要考虑拥塞控制？','网络容量有限，不受控地发送或重试会加剧拥塞；应用协议应依据路径和反馈限制速率。',[rfc(768),rfc(8085)],1,2,3),
s('ip','互联网协议','Internet Protocol',['IP'], '负责在互联网络之间按地址转发数据包的网络层协议族，IPv4和IPv6使用不同的地址及报头格式。IP提供尽力交付，不保证到达、按序或应用端口上的服务可用。','路由器依据目的IP前缀选择下一跳，将包逐段转发至目的网络。','IP地址标识网络层接口与路由位置；端口用于传输层服务分用，域名是另外的命名层。','把能ping通某IP等同于HTTPS服务正常。','IPv6地址长度是多少？','IPv6地址为128位；地址空间增加不自动解决应用访问控制、链路故障或服务监听配置问题。',[rfc(8200),rfc(791)],1,2,3),
s('dns','域名系统','Domain Name System',['DNS'], '通过分层命名与分布式记录查询将域名关联到地址、邮件路由等信息的系统，包含权威服务器、递归解析器及缓存。记录类型决定返回数据含义，不能简单理解为域名只对应一个IP。','同一域名可同时发布A和AAAA记录，也可通过CNAME关联另一个名称。','权威服务器持有某区域权威数据；递归解析器替客户端完成查询并缓存结果。','修改权威记录后期待所有客户端立即放弃旧缓存。','DNS缓存为何使切流不可能完全瞬时？','递归与客户端可能在记录有效期内保留旧值，连接也可能复用；切换应提前规划TTL和回滚。',[rfc(1034),rfc(1035)],1,2,3),
s('dhcp','动态主机配置协议','Dynamic Host Configuration Protocol',['DHCP'], '用于客户端自动获得地址及网络配置的协议，服务器按租约提供地址、网关和解析服务器等参数。它减少手工配置，但租约存在期限且需要处理续租、冲突与不可信服务器风险。','笔记本接入局域网后通过DHCP获得可用IPv4地址及默认网关。','DHCP分配网络配置；DNS查询名称记录，二者可联动但职责并不相同。','认为拿到DHCP地址就证明默认网关或互联网一定可达。','租约快到期时客户端需要做什么？','按协议尝试续租或重新绑定，失败且租约到期后不能继续假定该地址仍可合法使用。',[rfc(2131)],1,2,2),
s('nat','网络地址转换','Network Address Translation',['NAT'], '在网络边界改写数据包地址等字段并维护必要映射的机制，常用于私有地址访问外网。带端口转换的形式可让多个内部会话共享外部地址，但会改变端到端可达性。','家庭路由器把多台设备的连接映射到一个公网地址及不同外部端口。','地址转换是连通与地址复用机制；访问控制防火墙有不同职责，不能将NAT当完整安全策略。','认为所有NAT设备对外部发来的数据都具有同一接受规则。','为什么入站服务通常需要额外配置？','外部请求未必匹配已有映射，需按网络结构配置端口转发、公网入口或其他可达方案。',[rfc(3022)],2,2,2),
s('cidr','无类别域间路由','Classless Inter-Domain Routing',['CIDR'], '用地址与前缀长度表达网络地址块和路由聚合的方法，前缀位数描述共同的高位部分。它摆脱传统A/B/C类边界，支持更灵活的地址分配和最长前缀匹配路由。','192.0.2.0/24表示共享前24位的IPv4地址块，而不是一个单独主机名。','CIDR前缀长度不同于端口号；网络地址块大小与可分配主机数也不宜机械等同。','把/24理解成固定只有24个地址。','同一目的地匹配/16和/24路由时通常选哪个？','通常采用最长前缀匹配，优先更具体的/24，再按相应路由策略选择下一跳。',[rfc(4632)],2,2,2),
s('mtu','最大传输单元','Maximum Transmission Unit',['MTU'], '一条链路可承载的网络层数据包最大长度边界，不包含所有链路外层开销。路径MTU取决于路径上的限制，隧道和封装会进一步改变应用能够使用的有效载荷空间。','以太网常见MTU为1500字节，VPN封装后可用大小可能需要降低。','MTU约束IP包；MSS描述TCP段的数据部分，二者不是同一个字段。','看到1500就把1500字节应用数据直接视为不会分片的TCP负载。','路径MTU发现失败可能出现什么症状？','小包或握手成功但大包传输卡住；应检查必要ICMP反馈、封装开销和MSS设置。',[rfc(1191),rfc(8201)],2,3,2),
s('mss','最大报文段大小','Maximum Segment Size',['MSS'], 'TCP用于表达一端愿意接收的单个段最大数据字节数的参数，通常在连接建立时交换。实际发送还受路径MTU、协议头长度及发送策略限制，不代表每段必须达到该长度。','IPv4无额外选项且MTU为1500时，常见TCP数据上限为1460字节。','MSS通常不计IP头和TCP头；应用消息长度可超过MSS并拆成多个段。','将常见1460当成任何IP版本和隧道环境的固定值。','双方声明不同MSS会怎样？','每个方向根据对端接收能力及本方向路径约束决定段数据大小，两方向可以不同。',[rfc(6691),rfc(9293)],2,3,2),
s('rtt','往返时延','Round-Trip Time',['RTT'], '从发送某次交互到收到对应响应或确认所经历的往返时间，包含路径传播、排队与端点处理等因素。它通常随网络状态变化，测量口径决定是否包含应用处理时间。','跨地域请求需多次串行往返，即使响应体很小也可能产生明显延迟。','单向时延不是总能简单用RTT除以二得到，因为两个方向路径与排队可能不对称。','把一次ping的RTT当作所有HTTP请求固定耗时。','TCP为何不能用固定常数设置重传等待？','不同路径与拥塞状况下RTT及波动不同，应基于平滑测量和变化估计决定重传超时。',[rfc(6298)],1,2,3),
s('ttl','生存时间','Time to Live',['TTL'], '限制某类信息继续传播或被使用的范围的字段名称，其具体单位依协议而异。IPv4中路由器转发会减少该值以抑制循环；DNS记录TTL则表示缓存通常可保留的秒数。','traceroute逐步增大IP TTL，观察不同跳数处的超时反馈。','IP TTL实际用于跳数限制，不能把其值当DNS缓存秒数或精确墙钟寿命。','在不同协议里看到同名TTL就默认单位和含义相同。','IPv6中对应跳数限制字段叫什么？','叫Hop Limit；它明确表达转发跳数约束，仍与DNS记录缓存时间属于不同概念。',[rfc(791),rfc(8200),rfc(1035)],1,2,2),
s('arp','地址解析协议','Address Resolution Protocol',['ARP'], 'IPv4局域网中把下一跳IP地址解析为链路层地址的协议，节点通过请求、应答与缓存完成同一链路上的发送定位。它不负责把互联网任意远端IP直接解析成远端MAC。','主机访问外网时通常解析的是本地默认网关的MAC，而不是远端网站服务器MAC。','ARP用于IPv4邻居解析；IPv6主要使用邻居发现机制，不能照搬ARP报文。','把ARP缓存当成已认证且不可伪造的邻居身份表。','为什么跨路由器不能依靠ARP广播找远端主机？','ARP作用于本地链路广播域；跨网段通信由路由逐跳选择并分别解析本地下一跳。',[rfc(826),rfc(4861)],2,2,2),
s('icmp','互联网控制报文协议','Internet Control Message Protocol',['ICMP'], 'IP网络传递差错和诊断控制信息的协议族，用于目的不可达、超时及回显等信息。它不为业务数据提供可靠传输，且IPv4与IPv6相应协议的报文类型和作用并不完全相同。','路径MTU发现依赖某些不可达或包过大反馈，诊断工具也可使用回显报文。','ICMP不是TCP或UDP端口服务；ICMP回显失败不必然说明所有应用流量不可达。','为“安全”无差别屏蔽所有ICMP，导致连通性诊断和必要路径反馈失效。','ping不通但网页能打开合理吗？','合理，回显可能被过滤或限速，而TCP/QUIC应用路径仍可用；应按具体协议验证。',[rfc(792),rfc(4443)],1,2,2),
s('http','超文本传输协议','Hypertext Transfer Protocol',['HTTP'], '定义请求方法、资源标识、响应状态和表示元信息等语义的应用层协议，使用客户端请求和服务器响应进行交互。语义可由不同版本传输，不局限于某种文本报文布局。','客户端GET读取资源，服务器返回状态码、缓存控制和媒体类型等元信息。','HTTP语义和HTTP/1.1、HTTP/2、HTTP/3的消息编码及传输方式属于不同层面。','把所有非200状态都当作网络传输失败。','HTTP 204为何不应再返回普通响应内容？','204表示成功但无内容，应用应遵循对应消息语义，客户端不能按常规JSON正文盲目解析。',[rfc(9110)],1,2,3),
s('https','安全超文本传输访问','Hypertext Transfer Protocol Secure',['HTTPS'], '在HTTP访问中使用TLS等安全连接机制保护传输并验证端点身份的方案。正确验证证书和主机名是身份保证的重要条件，安全传输不会自动保证服务器业务逻辑或数据来源可信。','浏览器通过https地址连接服务并检查证书链和目标主机名。','HTTPS保护传输通道；数据库加密、授权检查和输入校验仍需分别实现。','忽略证书验证错误以“修复连接”，却破坏身份验证。','TLS在反向代理终止后内部链路怎样处理？','需按威胁模型保护代理到后端的链路和身份，不能因外部是HTTPS就假定内部明文永远安全。',[rfc(9110),rfc(8446)],1,2,3),
s('http2','HTTP第二版','Hypertext Transfer Protocol Version 2',['HTTP/2','H2'], '在保留HTTP语义的基础上以二进制帧、多路复用流和头部压缩组织通信的协议版本。多个逻辑流可共享一个TCP连接，但仍共同受底层TCP丢包恢复影响。','同一连接可交错承载多个资源响应，减少HTTP/1.1应用层串行等待。','HTTP/2流复用缓解应用层排队，却不消除TCP传输层的有序交付等待。','把HTTP/2描述成基于UDP，或认定它消除所有队头阻塞。','为何一个TCP丢包可能影响多个HTTP/2流？','底层字节流要等待缺失字节恢复，位于之后的帧可能暂时不能交给HTTP/2解析，即使属于其他流。',[rfc(9113)],2,3,2),
s('http3','HTTP第三版','Hypertext Transfer Protocol Version 3',['HTTP/3','H3'], '将HTTP语义映射到QUIC传输的协议版本，借助独立传输流降低不同请求之间因单一流丢包造成的交付耦合。它仍依赖拥塞控制、握手与正确的HTTP状态管理。','某个响应流重传时，其他已收到完整数据的流通常可继续向应用交付。','HTTP/3是HTTP映射；QUIC是其底层安全传输协议，二者不能当成同一个协议。','认为HTTP/3在任意网络下都必然比HTTP/2更快。','部署HTTP/3为什么还需关注UDP可达性？','QUIC通常运行在UDP上，网络过滤、代理和路径条件会影响使用，客户端可能需要回退其他HTTP版本。',[rfc(9114)],2,3,2),
s('quic','QUIC传输协议','QUIC',['QUIC'], '基于UDP构建、集成安全握手和多流传输能力的传输协议，提供可靠流与连接级拥塞控制等功能。QUIC在规范中是协议名称，不应编造必须展开的正式英文全称。','客户端切换网络后，可在协议条件允许时保持连接身份而不单纯依赖固定四元组。','QUIC并非“无可靠性的UDP加密版”；它自己实现确认、丢失恢复和流管理。','把早期项目名称的展开当作当前IETF规范中的正式全称。','多流是否意味着每条流完全不受其他流影响？','并不完全独立，连接层拥塞控制、流量限制和端点资源仍可形成共同瓶颈。',[rfc(9000)],2,3,2),
s('websocket','WebSocket协议','WebSocket',[], '在建立阶段与HTTP体系协作、随后提供双向消息通信的协议，双方可主动发送具有边界的消息，并使用控制帧管理连接。它不是持续重复发送普通HTTP请求的同义词。','协作编辑会话中客户端推送改动，服务器随时向其他客户端发送更新。','WebSocket提供双向消息；SSE主要用于服务器向客户端单向事件流，故障恢复机制也不同。','以为有了长连接就无需心跳、重连和消息顺序恢复设计。','重连后如何避免静默漏消息？','业务协议可使用事件序号、游标或快照恢复，并设置保留窗口；单纯重新连上不等于已补齐历史。',[rfc(6455)],1,2,3),
s('sse','服务器发送事件','Server-Sent Events',['SSE','EventSource'], '浏览器利用HTTP事件流持续接收服务器消息的机制，使用规定的文本格式表达事件、数据和事件编号。客户端可自动重连，但能否恢复遗漏事件取决于服务器对游标的支持。','任务进度接口以text/event-stream逐条发送进度，浏览器EventSource持续监听。','SSE主要是服务器到客户端的流；客户端提交数据通常另用HTTP请求，不等同双向WebSocket。','服务只发data行却缺少正确分隔，导致客户端迟迟不派发事件。','Last-Event-ID有什么作用？','重连时携带已收到的事件标识供服务端判断恢复位置；服务端必须有相应保留和补发策略才真正有效。',[src('WHATWG HTML：服务器发送事件','https://html.spec.whatwg.org/multipage/server-sent-events.html')],2,2,2),
s('rpc','远程过程调用','Remote Procedure Call',['RPC'], '把跨进程或跨主机的请求表达为调用某个远端操作的通信抽象，通常规定方法、参数、结果与错误编码。远程调用仍可能超时、部分失败或响应丢失，不能完全当本地函数使用。','客户端调用库存服务的Reserve方法，框架序列化参数并等待远端结果。','RPC强调操作调用；REST强调资源与统一接口约束，实际系统也可混合使用。','超时后直接认定远端没有执行，从而无条件重试产生重复副作用。','远端已提交但响应丢失如何处理？','使用幂等键、请求结果查询和可恢复的业务状态，明确重试边界而非只靠延长超时。',[rfc(5531)],1,2,3),
s('rest','表述性状态转移','Representational State Transfer',['REST'], '一种面向网络应用的架构风格，通过资源、表示与统一接口组织交互，并要求无状态交互等约束。它不等同于“URL里使用名词”或“HTTP接口返回JSON”的简单命名规范。','客户端取得带相关操作链接的资源表示，再根据统一语义进行后续交互。','REST是架构约束集合；HTTP是协议，使用HTTP并不能单独证明完全符合REST。','把无状态误解为服务器不能保存数据库或业务资源状态。','REST的无状态主要约束什么？','每次请求应携带理解请求所需的会话上下文，服务器可保存资源状态，但不依赖隐藏的客户端会话过程才能解释请求。',[src('Roy Fielding 博士论文第5章','https://ics.uci.edu/~fielding/pubs/dissertation/rest_arch_style.htm')],2,3,2),
s('cors','跨源资源共享','Cross-Origin Resource Sharing',['CORS'], '浏览器按服务器响应策略决定是否允许跨源脚本读取响应的机制，可涉及预检与凭据规则。它扩展同源策略中的受控共享，不是服务器通用鉴权，也不能限制所有非浏览器客户端。','前端位于另一个端口，API返回精确允许源后浏览器才向脚本暴露响应。','允许跨源读取与允许服务端执行请求不是一回事；简单请求可能已到达服务器。','把Access-Control-Allow-Origin当成防止未授权调用的安全边界。','带凭据请求能任意使用允许源星号吗？','不能按普通通配方式组合，应按规范返回具体允许源并正确处理凭据许可与缓存变化。',[src('WHATWG Fetch：CORS协议','https://fetch.spec.whatwg.org/#http-cors-protocol')],2,3,3),
s('cdn','内容分发网络','Content Delivery Network',['CDN'], '通过分布式边缘节点交付内容或代理请求的系统，利用靠近用户的缓存和路由降低源站压力与访问延迟。命中策略、过期和更新一致性影响用户实际看到的内容。','静态脚本文件带内容哈希，边缘节点缓存后为多个地区用户提供相同版本。','CDN并非只是一台反向代理；它涉及节点布局、请求调度、缓存及源站协作。','含用户身份的响应被公共缓存，造成其他用户读到私人内容。','如何减少静态文件版本更新时缓存混用？','使用内容寻址文件名、合适缓存头及可回滚发布清单；HTML入口通常采用与长期静态资源不同的缓存策略。',[rfc(6707),rfc(9111)],1,2,2),
s('uri','统一资源标识符','Uniform Resource Identifier',['URI'], '按统一语法标识资源的字符序列，可包含方案、权限部分、路径、查询和片段等组件。具体方案决定含义和解析规则，标识资源不表示一定能通过网络取得可下载文件。','https://example.test/a?q=1#part中查询与片段处于不同组件，浏览器通常不把片段发给服务器。','URL强调通过定位访问资源的形式；URI是更一般的标识概念，不能把所有URI视为HTTP地址。','在组件边界确定前任意整体解码，改变保留字符所表达的结构。','为什么转义斜杠和普通字母的转义不能随意等价处理？','保留字符可能承担路径分隔等语法作用，错误解码会改变资源定位或绕过路由与访问检查。',[rfc(3986)],1,2,2),
]},
];
const order=['os','network','database','distributed','security','engineering','operations'];
groups.sort((a,b)=>order.indexOf(a.id)-order.indexOf(b.id));
